"use strict";
// ===== RPG：物語（イベント）=====
// 書き方：["say", 話す人, "せりふ"]  "me"=主人公（男女で話し方が変わる）  ""=ナレーション
// 文字の置きかえ：{名前} {私}(僕/わたし) {くん}(くん/ちゃん)  [[男のとき|女のとき]]
// ほかの命令：choice / set / clr / if / warp / battle / gold / item / mem / join / heal / shop / gate / back / run / rename / end
const rpgN = (t) => ["say", "", t];
const rpgM = (t) => ["say", "me", t];
const rpgS = (w, t) => ["say", w, t];
const RPG_ENTER = {sendai:"sn_enter", tokyo:"tk_enter", white:"wh_enter", xmas:"xm_enter", labn:"lb_enter", future:"fu_enter"};

function rpgChain(list, last){ let r = [rpgS("ハルキ", last)]; for(let i = list.length - 1; i >= 0; i--) r = [["if", list[i][0], [rpgS("ハルキ", list[i][1])], r]]; return r; }

