// ===== ARE QUEST：土台（状態・成長・セーブ3枠・チート・声）=====
const $ = (id) => document.getElementById(id);
const esc = (t) => String(t == null ? "" : t).replace(/[&<>"']/g, (c) => ({"&":"&amp;", "<":"&lt;", ">":"&gt;", "\"":"&quot;", "'":"&#39;"})[c]);
const TQ_MAX_LV = 99, TQ_SLOTS = 3, TQ_MAX_PARTY = 4, TQ_MAX_GOLD = 9999999;
const G = {S:null, mode:"title", slot:0, rnd:Math.random, q:new URLSearchParams(location.search), cheatQueue:[], set:{voice:true, speed:0, pad:"auto"}, scripts:[], b:null, choices:null, tw:null, banner:null, hit:null, npcDir:{}, lastEnc:0, auto:false, grind:null, bg:"", menuTab:"", menuMsg:"", shopMsg:"", pend:null, toast:null};

// ---------------------------------------------------------------- 設定（この端末に保存）
function tqSettingsLoad(){ try{ Object.assign(G.set, JSON.parse(localStorage.getItem("tq_settings") || "{}")); }catch(_e){} }
function tqSettingsSave(){ try{ localStorage.setItem("tq_settings", JSON.stringify(G.set)); }catch(_e){} }

// ---------------------------------------------------------------- 文字の置きかえ（男女で話し方が変わる）
// ---- 主人公の「一人称」（自分のことを なんと よぶか）----
const TQ_PRONS = [["boku", "僕"], ["watashi", "私"], ["ore", "俺"], ["uchi", "うち"], ["washi", "わし"], ["orecchi", "おれっち"], ["jibun", "自分"], ["name", "自分の名前"], ["shujinko", "主人公"]];
function tqPron(s){
    const k = (s && s.pron) || (s && s.sex === "f" ? "watashi" : "boku");
    if(k === "name") return (s && s.name) || "主人公";
    if(k === "shujinko") return "主人公";
    const e = TQ_PRONS.find((x) => x[0] === k); return e ? e[1] : "僕";
}
function rpgFmt(t){
    const s = G.S || {sex:(G.draft && G.draft.sex) || "m", name:(G.draft && G.draft.name) || "主人公", pron:(G.draft && G.draft.pron) || ""}, m = s.sex === "m";
    return String(t).replace(/\[\[([^|\]]*)\|([^\]]*)\]\]/g, (_x, a, b) => m ? a : b)
        .replace(/\{名前\}/g, s.name).replace(/\{私\}/g, tqPron(s)).replace(/\{くん\}/g, m ? "くん" : "ちゃん");
}

// ---------------------------------------------------------------- 声（ブラウザの読み上げ・BGMなし）
// 男の声／女の声を えらぶ（端末に入っている日本語の声から名前で さがす）
const TQ_MALE_VOICE = /ichiro|otoya|takumi|hattori|keita|kenji|ryo|male|男|いちろう|おとや/i, TQ_FEMALE_VOICE = /kyoko|haruka|ayumi|nanami|sayaka|mizuki|o-?ren|female|女|google|きょうこ|はるか/i;
function tqPickVoice(g){
    try{
        const list = (window.speechSynthesis.getVoices() || []).filter((x) => /^ja/i.test(x.lang)); if(!list.length) return null;
        const male = list.find((x) => TQ_MALE_VOICE.test(x.name) && !/female/i.test(x.name)), fem = list.find((x) => TQ_FEMALE_VOICE.test(x.name) || !TQ_MALE_VOICE.test(x.name));
        if(g === "m") return male ? {voice: male, exact: true} : {voice: list[0], exact: false};
        return fem ? {voice: fem, exact: true} : {voice: list[0], exact: false};
    }catch(_e){ return null; }
}
// 主人公の よみがな：ひらがな／かたかな／ー／空白 だけ。空なら「なまえが かなだけ」のときは そのまま、そうでなければ ""（読み上げは なまえのまま）
function tqNormYomi(raw, name){
    let y = String(raw || "").normalize("NFKC").replace(/[\s　]+/g, "").trim();
    if(!y){ return /^[ぁ-ゖァ-ヺー・]+$/.test(String(name || "")) ? "" : ""; }
    if(Array.from(y).length > 20 || !/^[ぁ-ゖァ-ヺー・]+$/.test(y)) return null;
    return y;
}
function tqSpeak(text, who){
    if(!G.set.voice) return;
    try{
        if(!("speechSynthesis" in window) || typeof SpeechSynthesisUtterance !== "function") return;
        const ss = window.speechSynthesis; ss.cancel();
        let src = String(text); try{ if(G.S && G.S.yomi && G.S.name) src = src.split(G.S.name).join(G.S.yomi); }catch(_e){}
        const clean = src.replace(/\(ARE\)/g, "アレ").replace(/ARE/g, "アレ").replace(/[「」『』（）()…♪★☆💰▼]/g, "、").replace(/\s+/g, "");
        if(!clean.replace(/、/g, "").trim()) return;
        const key = who === "me" ? "me:" + (G.S ? G.S.sex : "m") : (who || "");
        const v = RPG_VOICES[key] || RPG_VOICES[""] || [1, 1];
        const u = new SpeechSynthesisUtterance(clean); u.lang = "ja-JP"; u.pitch = v[0]; u.rate = v[1];
        const g = v[0] <= 1.02 ? "m" : (v[0] >= 1.2 ? "f" : ""); const pk = g ? tqPickVoice(g) : null;
        const jp = pk ? pk.voice : (ss.getVoices() || []).find((x) => /^ja/i.test(x.lang)); if(jp) u.voice = jp;
        if(pk && !pk.exact) u.pitch = g === "m" ? Math.min(u.pitch, 1) * .6 : Math.max(u.pitch, 1.25);   // 男女の声が選べない端末は、高さで ちがいを出す
        ss.speak(u);
    }catch(_e){}
}
function tqSpeakStop(){ try{ window.speechSynthesis && window.speechSynthesis.cancel(); }catch(_e){} }

// ---------------------------------------------------------------- 状態
function tqNewState(prof){
    const S = {v:3, prof, name:prof.name, sex:prof.sex, map:"lab", x:8, y:9, dir:"up", px:8, py:9, lv:1, exp:0, gold:60, party:["hero"], m:{hero:{hp:1, mp:1}},
        items:{onigiri:3, coffee:1}, own:["w0", "a0", "c0"], eq:{w:"w0", a:"a0", c:"c0"}, f:{}, mem:[0, 0, 0, 0, 0, 0], steps:0, kills:0, gauge:0, trail:[], wh:{}, play:0, cx:{}, expmul:1, grinds:0};
    return S;
}
function tqMemCount(){ return G.S ? G.S.mem.reduce((a, b) => a + b, 0) : 0; }
function rpgCond(c){
    if(!c) return true;
    return String(c).split("|").some((alt) => alt.split("&").every((t0) => {      // 「A&B|C」＝（AかつB）または C
        let t = t0.trim(), neg = false; if(t[0] === "!"){ neg = true; t = t.slice(1); }
        const m = t.match(/^(mem|lv)>=(\d+)$/); let r;
        if(m) r = (m[1] === "mem" ? tqMemCount() : G.S.lv) >= Number(m[2]); else r = !!G.S.f[t];
        return neg ? !r : r;
    }));
}
function tqName(id){ return id === "hero" ? G.S.name : (RPG_CLASS[id].n || id); }
function tqLookOf(id){ return id === "hero" ? (G.S.sex === "m" ? "heroM" : "heroF") : TQ_LOOK_OF[id]; }
function tqStat(id){
    const S = G.S, c = RPG_CLASS[id], L = S.lv;
    if(S.cx.st999) return {maxhp:999, maxmp:999, atk:999, def:999, agi:999};
    const v = (a) => Math.round(a[0] + a[1] * L), e = S.eq;
    const st = {maxhp:v(c.hp), maxmp:v(c.mp), atk:v(c.atk), def:v(c.def), agi:v(c.agi)};
    const w = RPG_EQUIP[e.w].v, a = RPG_EQUIP[e.a].v + RPG_EQUIP[e.c].v, k = id === "hero" ? 1 : 0.6;
    st.atk += Math.round(w * k); st.def += Math.round(a * k);
    if(id === "hero" && S.prof && S.prof.pers){
        const b = S.prof.pers.bonus || {};
        st.maxhp = Math.round(st.maxhp * (b.hp || 1)); st.maxmp = Math.round(st.maxmp * (b.mp || 1)); st.atk = Math.round(st.atk * (b.atk || 1)); st.def = Math.round(st.def * (b.def || 1)); st.agi = Math.round(st.agi * (b.agi || 1));
    }
    return st;
}
function tqHealAll(){ G.S.party.forEach((id) => { const st = tqStat(id); G.S.m[id] = {hp:st.maxhp, mp:st.maxmp}; }); }
function tqClamp(){ G.S.party.forEach((id) => { if(!G.S.m[id]) G.S.m[id] = {hp:1, mp:1}; const st = tqStat(id), m = G.S.m[id]; m.hp = Math.min(m.hp, st.maxhp); m.mp = Math.min(m.mp, st.maxmp); }); }
function tqAddMember(id, force){
    const S = G.S; if(S.party.includes(id)) return false;
    if(!force && S.party.length >= TQ_MAX_PARTY) return false;
    S.party.push(id); const a = tqStat(id); S.m[id] = {hp:a.maxhp, mp:a.maxmp}; return true;
}
function tqGain(exp){
    const S = G.S, ups = [];
    if(S.lv >= TQ_MAX_LV){ S.exp = 0; return ups; }
    S.exp += Math.round(exp * (S.expmul || 1));
    while(S.lv < TQ_MAX_LV && S.exp >= rpgNeed(S.lv)){
        S.exp -= rpgNeed(S.lv);
        const before = {}; S.party.forEach((id) => { before[id] = tqStat(id); });
        S.lv++;
        S.party.forEach((id) => { const a = tqStat(id), m = S.m[id]; m.hp = Math.min(a.maxhp, m.hp + Math.max(0, a.maxhp - before[id].maxhp)); m.mp = Math.min(a.maxmp, m.mp + Math.max(0, a.maxmp - before[id].maxmp)); });
        let t = "レベル" + S.lv + " に あがった！";
        Object.keys(TQ_SKILLS).forEach((k) => { if(TQ_SKILLS[k].lv === S.lv) t += "\n" + S.name + "は「" + TQ_SKILLS[k].n + "」を おぼえた！"; });
        if(S.lv === 5 && S.party.includes("haruki")) t += "\nハルキは「ファイアウォール」を おぼえた！";
        if(S.lv === 3 && S.party.includes("akito")) t += "\nアキトは「チアアップ」を おぼえた！";
        ups.push(t);
    }
    if(S.lv >= TQ_MAX_LV){ S.exp = 0; ups.push("レベルが 最大（99）に なった！"); }
    if(ups.length && !(window.tqDiff && tqDiff() === "hard")){   // レベルが あがると HP・MPが ぜんかいふく（ハード以外。たおれた 仲間は そのまま）
        S.party.forEach((id) => { const a = tqStat(id), m = S.m[id]; if(m && m.hp > 0){ m.hp = a.maxhp; m.mp = a.maxmp; } });
        ups[ups.length - 1] += "\nHPと MPが ぜんかいふく した！";
    }
    return ups;
}
function tqSetLevel(n){
    const S = G.S; S.lv = Math.max(1, Math.min(TQ_MAX_LV, n)); S.exp = 0; tqClamp(); tqHealAll();
}
const TQ_SKILLS = {
    code:{n:"コードアタック", mp:3, lv:2, t:"one", p:1.8, d:"つよい 一撃"},
    recover:{n:"リカバリー", mp:4, lv:3, t:"ally", d:"なかまを かいふく"},
    beam:{n:"デバッグ・ビーム", mp:7, lv:6, t:"all", p:1.0, d:"てき ぜんたいに こうげき"},
    freeze:{n:"タイムストップ", mp:9, lv:10, t:"all", d:"てきの うごきを とめる"}
};

// ---------------------------------------------------------------- 冒険の書（セーブ3枠・この端末のブラウザに保存）
function tqSlotKey(i){ return "tq_save_" + i; }
function tqReadSlot(i){
    let raw; try{ raw = localStorage.getItem(tqSlotKey(i)); }catch(_e){ return null; }
    if(!raw) return null;
    try{ const r = JSON.parse(raw); if(r && r.data && r.data.v === 3 && RPG_MAPS[r.data.map]) return r; }catch(_e){}
    return {corrupted:true, name:"読み込み不可", saved_at:""};
}
function tqWriteSlot(i, rec){ try{ localStorage.setItem(tqSlotKey(i), JSON.stringify(rec)); return true; }catch(_e){ return false; } }
function tqNow(){ const d = new Date(), p = (n) => String(n).padStart(2, "0"); return d.getFullYear() + "/" + p(d.getMonth() + 1) + "/" + p(d.getDate()) + " " + p(d.getHours()) + ":" + p(d.getMinutes()); }
function tqSaveTo(i, name){
    if(!G.S) return {ok:false, msg:"セーブできる データが ありません。"};
    const nm = String(name || "").trim().slice(0, 24) || (G.S.name + "の冒険");
    const rec = {schema:1, name:nm, saved_at:tqNow(), data:JSON.parse(JSON.stringify(G.S))};
    if(!tqWriteSlot(i, rec)) return {ok:false, msg:"保存できませんでした。（ブラウザの保存が ゆるされていないかも）"};
    G.slot = i; G.saveName = nm; return {ok:true, msg:"冒険の書 " + i + " に 記録しました！"};
}
function tqAutoSave(){
    if(!G.S || !G.slot) return;
    const old = tqReadSlot(G.slot);
    tqWriteSlot(G.slot, {schema:1, name:(old && old.name && !old.corrupted) ? old.name : (G.saveName || G.S.name + "の冒険"), saved_at:tqNow(), data:JSON.parse(JSON.stringify(G.S))});
}
function tqCopySlot(a, b){
    const r = tqReadSlot(a); if(!r || r.corrupted) return {ok:false, msg:"コピーできる 冒険の書が ありません。"};
    if(a === b) return {ok:false, msg:"べつの 枠を えらんでください。"};
    const c = JSON.parse(JSON.stringify(r)); c.name = (r.name.slice(0, 24 - 5) + "のコピー"); c.saved_at = tqNow();
    return tqWriteSlot(b, c) ? {ok:true, msg:"冒険の書 " + b + " に コピーしました。"} : {ok:false, msg:"コピーできませんでした。"};
}
function tqDeleteSlot(i){ try{ localStorage.removeItem(tqSlotKey(i)); }catch(_e){} if(G.slot === i) G.slot = 0; return {ok:true, msg:"冒険の書 " + i + " を 消しました。"}; }
function tqRenameSlot(i, name){
    const r = tqReadSlot(i); if(!r || r.corrupted) return {ok:false, msg:"名前を変えられません。"};
    const nm = String(name || "").trim().slice(0, 24); if(!nm) return {ok:false, msg:"名前を入力してください。"};
    r.name = nm; tqWriteSlot(i, r); if(G.slot === i) G.saveName = nm; return {ok:true, msg:"名前を かえました。"};
}
function tqHasSaves(){ for(let i = 1; i <= TQ_SLOTS; i++){ const r = tqReadSlot(i); if(r && !r.corrupted) return true; } return false; }
function tqLoadFrom(i){
    const r = tqReadSlot(i); if(!r || r.corrupted) return {ok:false, msg:"読み込める 冒険の書が ありません。"};
    const base = tqNewState({name:"主人公", sex:"m"});
    const S = Object.assign(base, r.data); S.cx = Object.assign({}, r.data.cx || {}); S.f = Object.assign({}, r.data.f || {});
    try{ if(window.tqSubMigrate) tqSubMigrate(S); }catch(_e){}
    G.S = S; G.slot = i; G.saveName = r.name; G.scripts = []; G.b = null; G.auto = false; G.grind = null; try{ tqTempSync(S.map, true); }catch(_e){} tqClamp();
    return {ok:true, msg:"冒険の書 " + i + " を 読み込みました。"};
}
function tqPlayText(sec){ const m = Math.floor((sec || 0) / 60); return Math.floor(m / 60) + "時間" + String(m % 60).padStart(2, "0") + "分"; }

// ---------------------------------------------------------------- チートコード（暗号の指紋だけで照合）
function tqNorm(s){ return String(s || "").normalize("NFKC").toLowerCase().replace(/\s+/g, ""); }
function tqFindCheat(raw){
    const n = tqNorm(raw); if(!n) return null;
    const table = TQ_CHEATS, hit = (t) => { const h = tqStretch(t); const e = table.find((x) => x[0] === h); return e ? e[1] : null; };
    let id = hit(n); if(id) return {id, nums:[]};
    const nums = [], stem = n.split(",").map((tok) => tok.replace(/(\d+)$/, (m) => { nums.push(parseInt(m, 10)); return "#"; })).join(",");
    id = hit(stem); return id ? {id, nums} : null;
}
function tqToggle(key, label){ const c = G.S.cx; c[key] = !c[key]; return label + "を " + (c[key] ? "ON" : "OFF") + " に しました！"; }
function tqApplyCheat(raw){
    const f = tqFindCheat(raw);
    if(!f) return {ok:false, msg:"…ざんねん！ そんな コードは ないみたい。\n（ヒント：意外と たんじゅん かも？）"};
    if(!G.S){
        G.cheatQueue.push(String(raw)); return {ok:true, msg:"コードを 受けつけました！（ストック：ゲームを はじめると 反映されます）", queued:true};
    }
    const S = G.S, c = S.cx, n = f.nums;
    const all = (fn) => S.party.forEach((id) => fn(id, S.m[id]));
    let msg = "";
    switch(f.id){
        case "lvmax": tqSetLevel(99); msg = "全員が レベル99（最大）に なった！"; break;
        case "lvset": if(!(n[0] >= 1 && n[0] <= 99)) return {ok:false, msg:"レベルは 1〜99 で 指定してください。"}; tqSetLevel(n[0]); msg = "全員が レベル" + n[0] + " に なった！"; break;
        case "st999": c.st999 = true; tqClamp(); tqHealAll(); msg = "ステータスが ぜんぶ 999 に なった！"; break;
        case "goldmax": S.gold = TQ_MAX_GOLD; msg = "所持金が MAX（9,999,999G）に なった！"; break;
        case "goldadd": if(!(n[0] > 0)) return {ok:false, msg:"金額を 指定してください。"}; S.gold = Math.min(TQ_MAX_GOLD, S.gold + n[0]); msg = n[0] + "G を てにいれた！"; break;
        case "party5": case "party6": {
            const need = f.id === "party5" ? 1 : 2;
            if(n.length !== need) return {ok:false, msg:"NPC番号が " + need + "つ 必要です。"};
            const ids = n.map((x) => "n" + String(x).padStart(3, "0"));
            if(ids.some((x) => !RPG_CLASS[x])) return {ok:false, msg:"NPC番号は 001〜100 です。"};
            if(new Set(ids).size !== ids.length) return {ok:false, msg:"おなじ NPC は 2人 加えられません。"};
            if(ids.some((x) => S.party.includes(x))) return {ok:false, msg:"その NPC は すでに 仲間です。"};
            const target = f.id === "party5" ? 5 : 6;
            for(const sid of ["haruki", "akito", "kaito"]){ if(S.party.length >= target - ids.length) break; tqAddMember(sid, true); }
            if(S.party.length + ids.length > 6) return {ok:false, msg:"パーティは チートでも 6人までです。"};
            ids.forEach((x) => tqAddMember(x, true)); msg = ids.map((x) => RPG_CLASS[x].n).join("・") + " が なかまに くわわった！（" + S.party.length + "人パーティ）"; break;
        }
        case "bossally": {
            if(n.length !== 1 || !(n[0] >= 1 && n[0] <= 15)) return {ok:false, msg:"ボス番号は 01〜15 です。（例：BossAlly09）"};
            return tqCheatJoin(["b" + String(n[0]).padStart(2, "0")]);
        }
        case "miraboss": return tqCheatJoin(["mira_b"]);
        case "miraally": return tqCheatJoin(["mira"]);
        case "fullheal": tqHealAll(); msg = "みんなの HPと MPが 全回復した！"; break;
        case "revive": all((id, m) => { if(m.hp <= 0) m.hp = tqStat(id).maxhp; }); msg = "たおれた 仲間が ふっかつした！"; break;
        case "items99": Object.keys(RPG_ITEMS).forEach((k) => { S.items[k] = 99; }); msg = "どうぐが ぜんぶ 99こ に なった！"; break;
        case "bestgear": ["w6", "a6", "c4"].forEach((k) => { if(!S.own.includes(k)) S.own.push(k); S.eq[RPG_EQUIP[k].slot] = k; }); tqClamp(); msg = "さいきょうの そうびを てにいれた！"; break;
        case "expx10": S.expmul = 10; msg = "もらえる経験値が 10倍に！"; break;
        case "expx100": S.expmul = 100; msg = "もらえる経験値が 100倍に！！"; break;
        case "expx1": S.expmul = 1; msg = "経験値の倍率を 1倍に もどした。"; break;
        case "god": msg = tqToggle("god", "無敵モード"); break;
        case "onehit": msg = tqToggle("onehit", "ワンパンモード"); break;
        case "infmp": msg = tqToggle("infmp", "MPむげん"); break;
        case "areall": msg = tqToggle("areall", "ARE！ゲージ MAX固定"); break;
        case "arefull": S.gauge = 100; msg = "ARE！ゲージが MAX に なった！"; break;
        case "noenc": msg = tqToggle("noenc", "エンカウントなし"); break;
        case "encx3": msg = tqToggle("encx3", "エンカウント3倍"); break;
        case "speed": msg = tqToggle("speed", "あるくの 2倍速"); break;
        case "allgate": c.allgate = true; msg = "ゲートの 行き先が ぜんぶ ひらいた！"; break;
        case "memall": S.mem = [1, 1, 1, 1, 1, 1]; msg = "6つの メモリが ぜんぶ そろった！"; break;
        case "clear": ["e_sendai", "e_tokyo", "e_white", "e_xmas", "e_labn", "e_future", "intro_done", "xr_open"].forEach((k) => { S.f[k] = 1; }); S.mem = [1, 1, 1, 1, 1, 1]; ["e_n8", "e_n9", "e_n10", "e_n11"].forEach((k) => { S.f[k] = 1; }); msg = "ストーリーを ぜんぶ クリアした！（第2部も）"; G.afterCheat = "end"; break;
        case "bonus": S.f.xr_open = 1; S.f.e_n11 = 1; c.allgate = true; msg = "おまけの『XRアドベンチャー体験会』が ひらいた！（ゲートから いけます）"; break;
        case "rainbow": msg = tqToggle("rainbow", "にじいろモード"); break;
        case "showpos": msg = tqToggle("showpos", "座標ひょうじ"); break;
        case "voice": tqSpeak("チートコード、成功です。声は ちゃんと 出ています。", "アキト"); msg = G.set.voice ? "声の テスト！（聞こえない ときは ブラウザの 設定を 見てね）" : "声は いま オフです。せっていで オンに できます。"; break;
        case "cheat": S.gold = Math.min(TQ_MAX_GOLD, S.gold + 1000); msg = "…そのまんまの ことば だった！ ふふ、意外と たんじゅん でしょ？（1000G ゲット）"; break;
        case "off": ["god", "onehit", "infmp", "areall", "noenc", "encx3", "speed", "rainbow", "showpos"].forEach((k) => { c[k] = false; }); msg = "ON/OFFの チートを ぜんぶ OFF に しました。"; break;
        default: return {ok:false, msg:"そのコードは まだ つかえません。"};
    }
    tqAutoSave();
    return {ok:true, msg};
}
// チートで 仲間を くわえる（ふつうの 仲間は 4人まで／チートは 6人まで）
function tqCheatJoin(ids){
    const S = G.S, out = [];
    ids.forEach((id) => {
        if(S.party.includes(id)){ out.push(RPG_CLASS[id].n + " は すでに 仲間です。"); return; }
        if(id === "mira_b" && S.party.includes("mira")){ S.party = S.party.filter((x) => x !== "mira"); if(S.temp) delete S.temp.mira; }
        if(id === "mira" && S.party.includes("mira_b")){ out.push("ミラは すでに（ノイズクイーンの すがたで）仲間です。"); return; }
        if(S.party.length >= 6){ out.push("パーティは チートでも 6人までです。"); return; }
        tqAddMember(id, true); if(S.temp) delete S.temp[id]; out.push(RPG_CLASS[id].n + " が なかまに くわわった！（" + S.party.length + "人パーティ）");
    });
    tqAutoSave();
    return {ok:true, msg:out.join("\n")};
}
function tqFlushCheatQueue(){
    const out = [];
    while(G.cheatQueue.length){ const r = tqApplyCheat(G.cheatQueue.shift()); out.push(r.msg); }
    return out;
}


/* ==== game/ui.js ==== */
;(window.__AREB_S||(window.__AREB_S=[]))[11]=1;
"use strict";
// ===== 画面（タイトル／冒険の書／プロフィール／性格診断／あそびかた／せってい／チート）と入力 =====
const ACT = {};
const TQ_SPR = {};
const BGS = {title:"title", sendai_st:"sendai_st", aer:"aer"};

function toast(text, ms){
    const t = $("toast"); t.textContent = text; t.classList.add("on");
    clearTimeout(G.toastT); G.toastT = setTimeout(() => t.classList.remove("on"), ms || 2600);
}
function flash(){ const f = $("flash"); f.style.opacity = "0.9"; setTimeout(() => { f.style.opacity = "0"; }, 90); }
function setBg(key){
    const el = $("bg");
    if(!key){ el.classList.remove("on"); return; }
    el.style.backgroundImage = "url('./img/" + key + ".webp')"; el.classList.add("on");
}
// ---- 立ち絵（画像があれば画像、なければ見た目から描いた絵）----
function spriteURL(look){
    if(TQ_SPR[look]) return TQ_SPR[look];
    const c = document.createElement("canvas"); c.width = 120; c.height = 132; const g = c.getContext("2d"); g.scale(3.4, 3.4);
    g.translate(2, 0); rpgSprite(g, look, 0, 8, "down", 0, 0);
    return (TQ_SPR[look] = c.toDataURL());
}
function portraitHtml(who){
    if(!who) return "";
    if(who === "me"){ const f = G.S ? G.S.sex === "f" : (G.draft && G.draft.sex === "f"); return '<img src="./img/' + (f ? "girl" : "boy") + '.webp" alt="">'; }
    if(TQ_PORTRAIT_IMG[who]) return '<img src="./img/' + TQ_PORTRAIT_IMG[who] + '.webp" alt="">';
    if(TQ_PORTRAIT_LOOK[who] && RPG_LOOKS[TQ_PORTRAIT_LOOK[who]]) return '<img class="pix" src="' + spriteURL(TQ_PORTRAIT_LOOK[who]) + '" alt="">';
    return "";
}
function typeInto(el, text, instant){
    clearInterval(G.typeT); G.typing = null;
    if(!el) return;
    if(instant || !text){ el.textContent = text; tqAtArm(); return; }
    let i = 0; el.textContent = ""; G.typing = {el, text};
    G.typeT = setInterval(() => { i += 2; el.textContent = text.slice(0, i); if(i >= text.length){ clearInterval(G.typeT); G.typing = null; tqAtArm(); } }, 28);
}
function finishTyping(){ if(G.typing){ clearInterval(G.typeT); G.typing.el.textContent = G.typing.text; G.typing = null; tqAtArm(); return true; } return false; }
// ---- 会話オート：文字が出きったら、文の長さに合わせて待ってから 自動で つぎへ（選択肢・戦闘・ショップなどで止まる）
function tqAtArm(){
    clearTimeout(G.atT);
    if(!G.autoTalk || G.mode !== "talk" || !G.say) return;
    const len = Array.from(String(G.say.text || "")).length;
    G.atT = setTimeout(() => {
        if(!G.autoTalk || G.mode !== "talk" || G.typing || G.dlg) return;
        try{ if(window.speechSynthesis && window.speechSynthesis.speaking) { tqAtArm(); return; } }catch(_e){}
        tqSpeakStop(); pump();
    }, 900 + len * 70);
}
function tqAutoBtnHtml(){ return '<button class="btn sub' + (G.autoTalk ? " on" : "") + '" id="autoBtn" data-a="autoTalk" style="position:absolute;right:15cqw;top:6.8cqw;z-index:5">' + (G.autoTalk ? "▶▶ オート ON" : "▶ オート") + '</button>'; }
ACT.autoTalk = () => {
    G.autoTalk = !G.autoTalk; clearTimeout(G.atT);
    const bt = document.getElementById("autoBtn"); if(bt){ bt.className = "btn sub" + (G.autoTalk ? " on" : ""); bt.textContent = G.autoTalk ? "▶▶ オート ON" : "▶ オート"; }
    if(G.autoTalk && !G.typing) tqAtArm();
};
function winMsg(who, text, opts){
    opts = opts || {}; const por = portraitHtml(who === "me" ? "me" : who);
    const nm = who === "me" ? G.S.name : who;
    return (por ? '<div id="por">' + por + '</div>' : "") + '<div id="msg" class="win' + (por ? " hasp" : "") + '" data-tap="1">' + (nm ? '<span class="who">' + esc(nm) + '</span>' : "") + '<span id="mt" data-full="' + esc(text) + '"></span>' + (opts.next === false ? "" : '<span class="nx">▼</span>') + '</div>';
}

// ---------------------------------------------------------------- 描画の入口
function render(){
    const m = G.mode, ui = $("ui"); document.body.dataset.mode = m;
    let h = "";
    if(m === "title") h = viewTitle();
    else if(m === "slots") h = viewSlots();
    else if(m === "profile") h = viewProfile();
    else if(m === "persona") h = viewPersona();
    else if(m === "result") h = viewResult();
    else if(m === "help") h = viewHelp();
    else if(m === "settings") h = viewSettings();
    else if(m === "cheat") h = viewCheat();
    else if(m === "pack" && window.pkView) h = pkView();
    else h = fieldView();
    if(G.dlg) h += viewDlg();
    ui.innerHTML = h;
    const bgKey = m === "pack" ? "title" : m === "title" || m === "slots" || m === "profile" || m === "persona" || m === "result" || m === "help" || m === "settings" || m === "cheat" ? "title" : (G.bg || "");
    setBg(m === "battle" ? "" : bgKey);
    const full = ui.querySelector("#mt");
    if(full) typeInto(full, full.dataset.full);
    const first = navList()[0]; if(first) first.classList.add("on");
    document.body.classList.toggle("padoff", G.set.pad === "off"); document.body.classList.toggle("padon", G.set.pad === "on");
    $("btnVoice").textContent = G.set.voice ? "声：オン" : "声：オフ"; $("btnBgm").textContent = G.set.bgm === false ? "BGM：オフ" : "BGM：オン";
    if(window.fieldAfterRender) fieldAfterRender();
    const dlgIn = ui.querySelector("#dlgIn"); if(dlgIn) dlgIn.focus();
}
function navList(){
    const dlg = $("ui").querySelector("#dlg");
    const scope = dlg || $("ui");
    return Array.from(scope.querySelectorAll("[data-a]")).filter((e) => !e.disabled && e.offsetParent !== null);
}
function navMove(d){
    const l = navList(); if(!l.length) return;
    let i = l.findIndex((e) => e.classList.contains("on")); l.forEach((e) => e.classList.remove("on"));
    i = i < 0 ? 0 : (i + d + l.length) % l.length; l[i].classList.add("on"); l[i].scrollIntoView({block:"nearest"});
}
function navOk(){ const l = navList(); const e = l.find((x) => x.classList.contains("on")) || l[0]; if(e) e.click(); }

// ---------------------------------------------------------------- ダイアログ（はい／いいえ・入力）
function viewDlg(){
    const d = G.dlg;
    if(d.type === "confirm") return '<div id="dlg" class="win panel sm" style="z-index:8;text-align:center"><div style="white-space:pre-wrap;margin:.6cqw 0 1.4cqw">' + esc(d.text) + '</div><div class="row" style="justify-content:center"><button class="btn" data-a="dlgyes">はい</button><button class="btn sub" data-a="dlgno">いいえ</button></div></div>';
    return '<div id="dlg" class="win panel sm" style="z-index:8"><div>' + esc(d.text) + '</div><input id="dlgIn" type="text" maxlength="' + (d.max || 24) + '" value="' + esc(d.value || "") + '" style="width:100%;margin:.8cqw 0"><div class="row" style="justify-content:center"><button class="btn" data-a="dlgok">けってい</button><button class="btn sub" data-a="dlgno">やめる</button></div></div>';
}
function askYes(text, fn){ G.dlg = {type:"confirm", text, fn}; render(); }
function askText(text, value, fn, max){ G.dlg = {type:"prompt", text, value, fn, max}; render(); }
ACT.dlgyes = () => { const f = G.dlg.fn; G.dlg = null; render(); if(f) f(); };
ACT.dlgno = () => { G.dlg = null; render(); };
ACT.dlgok = () => { const v = ($("dlgIn") || {}).value || "", f = G.dlg.fn; G.dlg = null; render(); if(f) f(v); };

// ---------------------------------------------------------------- タイトル
function viewTitle(){
    G.draft = null;
    return '<div id="tm" class="win"><button class="opt" data-a="tNew">はじめから</button><button class="opt" data-a="tLoad">つづきから</button><button class="opt" data-a="tHelp">あそびかた</button><button class="opt" data-a="tSet">せってい</button><button class="opt" data-a="tMovie">🎬 しょうかい映像</button>' + '<button class="opt" data-a="tPad">🎮 ボタン設定</button>' + (window.AREGameNav && AREGameNav.canShow() ? '<button class="opt" data-a="tGames">🎮 ほかのゲーム</button>' : "") + (G.installEv ? '<button class="opt" data-a="tInstall">📲 アプリとして インストール</button>' : "") + '<button class="opt" data-a="tCheat">🔑 チート</button></div>' +
        '<div class="foot">ARE QUEST 〜そういうときは、AREだ！〜　／　タップ・矢印キー+Enter・コントローラー（A=けってい B=もどる）で えらべます</div>';
}
ACT.tGames = () => { if(window.AREGameNav) AREGameNav.open({before: () => { try{ if(window.tqAutoSave && G.S) tqAutoSave(); }catch(_e){} }}); };
ACT.tPad = () => { if(window.AREPadMap) AREPadMap.open(); };
ACT.tInstall = () => { const ev = G.installEv; if(!ev) return; try{ ev.prompt(); if(ev.userChoice) ev.userChoice.then(() => { G.installEv = null; if(G.mode === "title") render(); }); }catch(_e){} };
ACT.tNew = () => { G.slotCtx = "new"; G.slotFrom = "title"; G.slotPick = null; G.mode = "slots"; render(); };
ACT.tLoad = () => { if(!tqHasSaves()){ toast("まだ 冒険の書が ありません。『はじめから』で 冒険を はじめよう！"); return; } G.slotCtx = "load"; G.slotFrom = "title"; G.slotPick = null; G.mode = "slots"; render(); };
ACT.tHelp = () => { G.helpFrom = "title"; G.mode = "help"; render(); };
ACT.tSet = () => { G.setFrom = "title"; G.mode = "settings"; render(); };
// ==================================================================
//  ★ しょうかい映像のリンク ★
//  ↓ ここにリンクはりましょう（Google ドライブ / YouTube / 直接のmp4のURL が使えます）
//    例）const TQ_MOVIE_URL = "https://drive.google.com/file/d/ここにID/view?usp=sharing";
//    ※ Google ドライブは「リンクを知っている全員が閲覧可」にしておくこと
// ==================================================================
const TQ_MOVIE_URL = "https://drive.google.com/file/d/13xEw4xRGQiK9crsSKwPuLiYxyC1V-xlJ/view?usp=sharing";

function tqMovieEmbed(u){
    u = String(u || "").trim(); if(!u) return null;
    let m = u.match(/drive\.google\.com\/file\/d\/([\w-]+)/) || u.match(/drive\.google\.com\/open\?id=([\w-]+)/);
    if(m) return {type:"frame", src:"https://drive.google.com/file/d/" + m[1] + "/preview"};
    m = u.match(/youtu\.be\/([\w-]{6,})/) || u.match(/youtube\.com\/watch\?[^#]*v=([\w-]{6,})/) || u.match(/youtube\.com\/(?:embed|shorts)\/([\w-]{6,})/);
    if(m) return {type:"frame", src:"https://www.youtube.com/embed/" + m[1] + "?autoplay=1&rel=0"};
    if(/^https:\/\//.test(u)) return {type:"video", src:u};
    return null;
}
ACT.tMovie = () => {
    if(document.getElementById("movBox")) return;
    const emb = tqMovieEmbed(TQ_MOVIE_URL);
    G.moviePlaying = true; if(typeof tqBgmStop === "function") tqBgmStop();
    const box = document.createElement("div"); box.id = "movBox";
    let inner = "";
    if(emb && emb.type === "frame") inner = '<iframe id="movV" src="' + esc(emb.src) + '" allow="autoplay; fullscreen" allowfullscreen></iframe>';
    else if(emb) inner = '<video id="movV" src="' + esc(emb.src) + '" controls autoplay playsinline></video>';
    box.innerHTML = inner + '<div id="movMsg">' + (emb ? "" : "しょうかい映像は じゅんび中です。") + '</div><button type="button" id="movX">✕ とじる</button>';
    $("stage").appendChild(box);
    const v = $("movV"), close = () => { try{ if(v && v.pause) v.pause(); }catch(_e){} box.remove(); G.moviePlaying = false; if(typeof tqBgmSync === "function") tqBgmSync(); };
    $("movX").addEventListener("click", close);
    if(v && v.tagName === "VIDEO"){ v.addEventListener("ended", close); v.addEventListener("error", () => { $("movMsg").textContent = "映像を よみこめませんでした。"; }); }
};
ACT.tCheat = () => { G.cheatFrom = "title"; G.cheatMsg = ""; G.mode = "cheat"; render(); };

// ---------------------------------------------------------------- 冒険の書（3枠）
function mapNameOf(id){ return RPG_MAPS[id] ? RPG_MAPS[id].name : id; }
function viewSlots(){
    const ctx = G.slotCtx, pick = G.slotPick, title = ctx === "new" ? "どの 冒険の書に 記録しますか？" : ctx === "save" ? "冒険の書に セーブ" : "どの 冒険の書を ひらきますか？";
    let h = '<div class="win panel scroll"><h2>📖 冒険の書</h2><div class="meta" style="margin-bottom:.6cqw">' + (pick ? "コピー先の 枠を えらんでください。" : title) + '</div><div class="slots">';
    for(let i = 1; i <= TQ_SLOTS; i++){
        const r = tqReadSlot(i), cur = G.slot === i && ctx === "save";
        h += '<div class="slot' + (pick && pick.from !== i ? " pick" : "") + '"><b>冒険の書 ' + i + (cur ? "（いま）" : "") + '</b>';
        if(!r) h += '<div class="meta" style="margin:2cqw 0">— あきわく —</div>';
        else if(r.corrupted) h += '<div class="err">読み込めません</div>';
        else{
            const d = r.data; h += '<div style="font-size:2cqw;color:#fff">' + esc(r.name) + '</div><div class="meta">' + esc(d.name) + '　Lv' + d.lv + '　メモリ ' + d.mem.reduce((a, b) => a + b, 0) + '/6</div><div class="meta">' + esc(mapNameOf(d.map)) + '</div><div class="meta">プレイ ' + tqPlayText(d.play) + '</div><div class="meta">' + esc(r.saved_at) + '</div>';
        }
        h += '<div class="sb">';
        if(pick){ if(pick.from !== i) h += '<button class="btn" data-a="slotCopyTo" data-v="' + i + '">ここへコピー</button>'; }
        else if(ctx === "new") h += '<button class="btn" data-a="slotNew" data-v="' + i + '">この枠ではじめる</button>';
        else{
            if(ctx === "save") h += '<button class="btn" data-a="slotSave" data-v="' + i + '">セーブ</button>';
            if(r && !r.corrupted) h += '<button class="btn" data-a="slotLoad" data-v="' + i + '">ロード</button>';
            if(r && !r.corrupted) h += '<button class="btn sub" data-a="slotCopy" data-v="' + i + '">コピー</button><button class="btn sub" data-a="slotName" data-v="' + i + '">名前</button>';
            if(r) h += '<button class="btn sub" data-a="slotDel" data-v="' + i + '">消す</button>';
        }
        h += '</div></div>';
    }
    h += '</div><div class="row" style="margin-top:1cqw"><button class="btn sub" data-a="' + (pick ? "slotPickCancel" : "slotBack") + '">もどる</button></div><div class="meta" style="margin-top:.5cqw">※ 冒険の書は、この端末の ブラウザの中に 保存されます。（ゲーム中は 自動でも 記録されます）</div></div>';
    return h;
}
ACT.slotBack = () => { if(G.slotFrom === "menu"){ G.mode = "menu"; G.menuTab = "main"; } else G.mode = "title"; render(); };
ACT.slotPickCancel = () => { G.slotPick = null; render(); };
ACT.slotNew = (v) => {
    const i = Number(v), r = tqReadSlot(i), go = () => { G.newSlot = i; G.draft = {name:"主人公", sex:"m", month:"", day:"", answers:[], q:0}; G.mode = "profile"; render(); };
    if(r) askYes("冒険の書 " + i + " には データが あります。\n上書きして はじめますか？", go); else go();
};
ACT.slotSave = (v) => {
    const i = Number(v), r = tqReadSlot(i), run = (nm) => { const res = tqSaveTo(i, nm); toast(res.msg); if(res.ok && typeof tqSePlay === "function") tqSePlay("save"); render(); };
    const go = () => askText("冒険の書 " + i + " の 名前（24文字まで）", (r && !r.corrupted ? r.name : (G.saveName || G.S.name + "の冒険")), run, 24);
    if(r) askYes("冒険の書 " + i + " に 上書きセーブしますか？", go); else go();
};
ACT.slotLoad = (v) => {
    const i = Number(v), res = tqLoadFrom(i); if(!res.ok){ toast(res.msg); return; }
    tqSettingsLoad(); enterGame(res.msg);
};
ACT.slotCopy = (v) => { G.slotPick = {from:Number(v)}; render(); };
ACT.slotCopyTo = (v) => {
    const to = Number(v), from = G.slotPick.from, run = () => { const res = tqCopySlot(from, to); G.slotPick = null; toast(res.msg); render(); };
    if(tqReadSlot(to)) askYes("冒険の書 " + to + " を 上書きして コピーしますか？", run); else run();
};
ACT.slotName = (v) => { const i = Number(v), r = tqReadSlot(i); askText("あたらしい 名前（24文字まで）", r ? r.name : "", (nm) => { const res = tqRenameSlot(i, nm); toast(res.msg); render(); }, 24); };
ACT.slotDel = (v) => { const i = Number(v); askYes("冒険の書 " + i + " を 消します。\nもとに もどせません。いいですか？", () => { const res = tqDeleteSlot(i); toast(res.msg); if(G.slotCtx === "load" && !tqHasSaves()){ G.mode = "title"; } render(); }); };

// ---------------------------------------------------------------- プロフィール（名前・性別・誕生日→星座）
function tqSuggestName(){ let n = ""; try{ n = localStorage.getItem("tq_suggest_name") || ""; }catch(_e){} return n || G.q.get("name") || ""; }
function stp(k, d){ return '<button class="btn sub" style="min-width:3.2cqw;padding:.2cqw .8cqw" data-a="pStep" data-v="' + k + ":" + d + '" aria-label="' + (k === "mon" ? "月" : "日") + (d < 0 ? "を へらす" : "を ふやす") + '">' + (d < 0 ? "◀" : "▶") + '</button>'; }
function viewProfile(){
    const d = G.draft, sug = tqSuggestName().trim().slice(0, 10);
    let mo = '<option value="">月</option>', da = '<option value="">日</option>';
    for(let i = 1; i <= 12; i++) mo += '<option value="' + i + '"' + (String(d.month) === String(i) ? " selected" : "") + '>' + i + '</option>';
    for(let i = 1; i <= 31; i++) da += '<option value="' + i + '"' + (String(d.day) === String(i) ? " selected" : "") + '>' + i + '</option>';
    const z = tqZodiac(d.month, d.day);
    return '<div class="win panel sm scroll"><h2>🧑 プロフィール</h2><label for="pName">主人公の なまえ（10文字まで・はじめは「主人公」）</label><input id="pName" type="text" maxlength="10" value="' + esc(d.name) + '" style="width:100%">' +
        '<label for="pYomi">よみがな（ひらがな・かたかな。声で よむとき つかいます）</label><input id="pYomi" type="text" maxlength="20" value="' + esc(d.yomi || "") + '" placeholder="例：たろう（漢字の名前のときは 入れてね）" style="width:100%">' +
        (sug ? '<div class="row" style="margin:.5cqw 0"><button class="btn sub" data-a="pUse">⭐ プロフィールの名前「' + esc(sug) + '」を つかう（おすすめ）</button></div>' : '<div class="meta">（チャットの プロフィールの 名前を おすすめします。ゲームの 中でも かえられます）</div>') +
        '<label>せいべつ（話し方が かわります）</label><div class="row"><button class="btn' + (d.sex === "m" ? "" : " sub") + '" data-a="pSex" data-v="m">🧑 男の子（僕）</button><button class="btn' + (d.sex === "f" ? "" : " sub") + '" data-a="pSex" data-v="f">👩 女の子（私）</button></div>' +
        '<label for="pPron">自分の よびかた（一人称）</label><select id="pPron"><option value="">おまかせ（男の子＝僕／女の子＝私）</option>' + TQ_PRONS.map((p) => '<option value="' + p[0] + '"' + (d.pron === p[0] ? " selected" : "") + '>' + esc(p[0] === "name" ? "自分の名前（" + (d.name || "主人公") + "）" : p[1]) + '</option>').join("") + '</select>' +
        '<label>たんじょう日（星座が わかるよ）</label><div class="row">' + stp("mon", -1) + '<select id="pMon">' + mo + '</select> 月 ' + stp("mon", 1) + stp("day", -1) + '<select id="pDay">' + da + '</select> 日 ' + stp("day", 1) + '</div><div class="meta">コントローラーの人は ◀ ▶ で えらべます。</div>' +
        '<div class="zodiac" id="zod">' + zodHtml(z) + '</div><div class="err" id="perr"></div><div class="row"><button class="btn sub" data-a="pBack">もどる</button><button class="btn" data-a="pNext">つぎへ ▶</button></div></div>';
}
function zodHtml(z){ return z ? z.mark + " " + esc(z.name) + '<div class="meta">' + esc(z.text) + '</div>' : '<span class="meta">月と日を えらぶと、星座が ひょうじされます。</span>'; }
function keepDraft(){ const d = G.draft; if(!d) return; if($("pName")) d.name = $("pName").value; if($("pYomi")) d.yomi = $("pYomi").value; if($("pMon")) d.month = $("pMon").value; if($("pDay")) d.day = $("pDay").value; if($("pPron")) d.pron = $("pPron").value; }
// ◀ ▶ ボタンで 月・日・呼び方を えらぶ（コントローラーだけでも 進められるように）
ACT.pStep = (v) => {
    keepDraft(); const [k, ds] = String(v).split(":"), n = Number(ds), d = G.draft;
    const cyc = (cur, max) => { const c = Number(cur) || 0; return String(c ? ((c - 1 + n + max) % max) + 1 : (n > 0 ? 1 : max)); };
    if(k === "mon") d.month = cyc(d.month, 12); else if(k === "day") d.day = cyc(d.day, 31);
    render();
    const b = Array.from($("ui").querySelectorAll('[data-a="pStep"]')).find((e) => e.dataset.v === v);
    if(b){ navList().forEach((e) => e.classList.remove("on")); b.classList.add("on"); }
};
ACT.pUse = () => { const sug = tqSuggestName().trim().slice(0, 10); if(sug){ keepDraft(); G.draft.name = sug; render(); toast("プロフィールの 名前を 使います。"); } };
ACT.pSex = (v) => { keepDraft(); G.draft.sex = v; render(); };
ACT.pBack = () => { keepDraft(); G.mode = "title"; render(); };
ACT.pNext = () => {
    keepDraft(); const d = G.draft, e = $("perr"), nm = d.name.trim();
    if(!nm){ e.textContent = "主人公の なまえを いれてください。"; return; }
    if(Array.from(nm).length > 10){ e.textContent = "なまえは 10文字までです。"; return; }
    if(!d.month || !d.day){ e.textContent = "たんじょう日の 月と日を えらんでください。"; return; }
    const z = tqZodiac(d.month, d.day); if(!z){ e.textContent = "その月に ない 日付です。"; return; }
    const ym = tqNormYomi(d.yomi, nm); if(ym === null){ e.textContent = "よみがなは ひらがな・かたかなで 入れてください（20文字まで）。"; return; }
    d.yomi = ym; d.name = nm; d.zodiac = z; d.answers = []; d.q = 0; G.mode = "persona"; render();
};
// ---------------------------------------------------------------- 性格診断（3つの質問・はい／いいえ）
function viewPersona(){
    const d = G.draft, i = d.q;
    return '<div class="win panel sm"><h2>🔮 性格診断（' + (i + 1) + '/3）</h2><div class="q">' + esc(TQ_QUESTIONS[i]) + '</div><div class="qb"><button class="btn" data-a="qAns" data-v="1">はい</button><button class="btn" data-a="qAns" data-v="0">いいえ</button></div>' +
        '<div class="row" style="margin-top:2cqw"><button class="btn sub" data-a="qBack">もどる</button></div></div>';
}
ACT.qAns = (v) => { const d = G.draft; d.answers[d.q] = v === "1"; if(d.q >= 2){ d.pers = tqPersonality(d.answers); G.mode = "result"; } else d.q++; render(); };
ACT.qBack = () => { const d = G.draft; if(d.q > 0){ d.q--; d.answers.length = d.q; render(); } else { G.mode = "profile"; render(); } };
function viewResult(){
    const d = G.draft, p = d.pers, b = p.bonus, bt = Object.keys(b).map((k) => ({hp:"HP", mp:"MP", atk:"こうげき", def:"ぼうぎょ", agi:"すばやさ"})[k] + " +" + Math.round((b[k] - 1) * 100) + "%").join("　");
    return '<div class="win panel sm"><h2>✨ 診断の けっか</h2><div style="font-size:2.4cqw"><b>' + esc(d.name) + '</b>（20歳・' + (d.sex === "m" ? "男" : "女") + '）</div><div class="zodiac">' + zodHtml(d.zodiac) + '</div>' +
        '<h3>あなたの 性格：' + esc(p.name) + '</h3><div>' + esc(p.desc) + '</div><div class="chips"><span class="chip">せいちょうボーナス：' + esc(bt) + '</span></div>' +
        '<div class="row" style="margin-top:1.2cqw"><button class="btn sub" data-a="rBack">さいごの 質問に もどる</button><button class="btn" data-a="rStart">⚔️ ぼうけんを はじめる</button></div></div>';
}
ACT.rBack = () => { const d = G.draft; d.q = 2; d.answers.length = 2; G.mode = "persona"; render(); };
ACT.rStart = () => {
    const d = G.draft;
    G.S = tqNewState({name:d.name, sex:d.sex, month:Number(d.month), day:Number(d.day), zodiac:d.zodiac, answers:d.answers.slice(), pers:d.pers});
    G.slot = G.newSlot; G.saveName = d.name + "の冒険"; tqHealAll(); G.scripts = []; G.b = null; G.auto = false; G.grind = null; G.S.pron = d.pron || ""; G.S.yomi = d.yomi || "";
    tqSaveTo(G.slot, G.saveName); G.draft = null;
    enterGame(""); runScript(RPG_EV.lab_intro);
};
// ---------------------------------------------------------------- あそびかた・せってい
function helpText(){
    return "【ものがたり】\n未来の ARE かいはつラボから、過去の世界へ タイムスリップ！ ノイズ（かわいい モンスター）に 持ち去られた『大事なメモリ』6つを 取りもどして、ARE を 完成させよう。\n\n" +
        "【そうさ】\n🎮 コントローラー（Switchプロコン等）：十字キー／左スティック＝いどう、A＝けってい、B＝もどる、X・＋＝メニュー\n・おわる：右下の「✖ おわる」かタイトルの「ゲームをおわる」（自動で記録されます）\nいどう：矢印キー／WASD／画面の ボタン（長おしで 連続）\nはなす・しらべる・けってい：Enter／Z／スペース／Aボタン\nメニュー：X／M／メニューボタン　もどる：X／Esc\n\n" +
        "【たたかい】\nコマンドを えらんで たたかう。なかまは 自動で こうどう。『オート』を ONに すると 自動で 戦うよ。『ARE！ゲージ』が MAX で ひっさつ技！\n\n" +
        "【ならではの きのう】\n・パーティは 最大4人\n・自動レベル上げ（メニュー→じどう）\n・冒険の書は 3つ（いつでも セーブ）\n・声は ブラウザの 読み上げ／BGMは game/bgm の mp3 を ループ再生\n・🔑チート：ひみつの コードを さがそう！ ヒント：意外と たんじゅん。";
}
function viewHelp(){ return '<div class="win panel scroll"><h2>📘 あそびかた</h2><div style="white-space:pre-wrap;font-size:1.95cqw">' + esc(helpText()) + '</div><div class="row" style="margin-top:1cqw"><button class="btn" data-a="hBack">もどる</button></div></div>'; }
ACT.hBack = () => { if(G.helpFrom === "menu"){ G.mode = "menu"; G.menuTab = "main"; } else G.mode = "title"; render(); };
function viewSettings(){
    const s = G.set, sp = ["ふつう", "はやい", "すごくはやい"][s.speed || 0], pad = {auto:"じどう", on:"ひょうじ", off:"ひひょうじ"}[s.pad || "auto"];
    return '<div class="win panel sm scroll"><h2>⚙️ せってい</h2><div class="card"><div class="row"><button class="btn" data-a="sVoice">🔊 声（読み上げ）：' + (s.voice ? "オン" : "オフ") + '</button></div><div class="meta">ブラウザの 設定で ゆるされていないと 鳴りません。</div></div>' +
        '<div class="card"><div class="row"><button class="btn" data-a="sBgm">🎵 BGM：' + (s.bgm === false ? "オフ" : "オン") + '</button><button class="btn sub" data-a="sBgmVol">音量：' + ["小", "中", "大"][s.bgmVol == null ? 1 : s.bgmVol] + '</button></div><div class="meta">曲は game/bgm/ に置いた mp3 が 鳴ります（ずっと ループ）。</div></div>' +
        (G.S ? '<div class="card"><div class="meta">自分の よびかた（一人称）</div><div class="row">' + TQ_PRONS.map((p) => '<button class="btn' + (tqPronKey() === p[0] ? "" : " sub") + '" data-a="sPron" data-v="' + p[0] + '">' + esc(p[0] === "name" ? G.S.name : p[1]) + '</button>').join("") + '</div></div>' : "") +
        '<div class="card"><div class="row"><button class="btn" data-a="sSpeed">⏩ オート戦闘の はやさ：' + sp + '</button></div></div>' +
        '<div class="card"><div class="row"><button class="btn" data-a="sPad">🎮 タッチ ボタン：' + pad + '</button><button class="btn sub" data-a="sFull">全画面</button></div><div class="meta">スマホ・タブレットは よこむき が おすすめ。</div></div>' +
        '<div class="row"><button class="btn" data-a="sBack">もどる</button></div></div>';
}
ACT.sVoice = () => { G.set.voice = !G.set.voice; if(!G.set.voice) tqSpeakStop(); tqSettingsSave(); render(); };
function tqPronKey(){ return (G.S && G.S.pron) || (G.S && G.S.sex === "f" ? "watashi" : "boku"); }
ACT.sPron = (v) => { if(G.S && TQ_PRONS.some((p) => p[0] === v)){ G.S.pron = v; tqAutoSave(); } render(); };
ACT.sBgm = () => { G.set.bgm = G.set.bgm === false; tqSettingsSave(); if(G.set.bgm === false) tqBgmStop(); else tqBgmSync(); $("btnBgm").textContent = G.set.bgm === false ? "BGM：オフ" : "BGM：オン"; render(); };
ACT.sBgmVol = () => { G.set.bgmVol = ((G.set.bgmVol == null ? 1 : G.set.bgmVol) + 1) % 3; tqSettingsSave(); tqBgmSync(); render(); };
ACT.sSpeed = () => { G.set.speed = ((G.set.speed || 0) + 1) % 3; tqSettingsSave(); render(); };
ACT.sPad = () => { G.set.pad = G.set.pad === "auto" ? "on" : G.set.pad === "on" ? "off" : "auto"; tqSettingsSave(); render(); };
ACT.sFull = () => toggleFullscreen();
ACT.sBack = () => { if(G.setFrom === "menu"){ G.mode = "menu"; G.menuTab = "main"; } else G.mode = "title"; render(); };
function toggleFullscreen(){
    try{
        if(document.fullscreenElement){ document.exitFullscreen(); return; }
        const el = document.documentElement;
        (el.requestFullscreen ? el.requestFullscreen() : Promise.reject()).then(() => { try{ screen.orientation && screen.orientation.lock && screen.orientation.lock("landscape").catch(() => {}); }catch(_e){} }).catch(() => toast("このブラウザでは 全画面に できません。"));
    }catch(_e){ toast("このブラウザでは 全画面に できません。"); }
}
// ---------------------------------------------------------------- チート
function viewCheat(){
    const on = G.S ? Object.keys(G.S.cx).filter((k) => G.S.cx[k] === true) : [];
    const names = {god:"無敵", onehit:"ワンパン", infmp:"MPむげん", areall:"ARE固定", noenc:"エンカなし", encx3:"エンカ3倍", speed:"2倍速", rainbow:"にじ", showpos:"座標", st999:"ステ999", allgate:"ゲート全開"};
    return '<div class="win panel sm"><h2>🔑 チートコード</h2><div class="meta">ひみつの コードを 入れてみよう。' + (G.S ? "" : "（いまは ストック：ゲームを はじめると 反映されます）") + '</div>' +
        '<input id="cInput" type="text" maxlength="40" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="コードを にゅうりょく" style="width:100%;margin:1cqw 0">' +
        '<div class="row"><button class="btn" data-a="cGo">けってい</button><button class="btn sub" data-a="cBack">もどる</button></div>' +
        '<div id="cMsg" style="white-space:pre-wrap;margin-top:1cqw;min-height:5cqw;color:' + (G.cheatOk ? "var(--ok)" : "#ffd1d1") + '">' + esc(G.cheatMsg || "") + '</div>' +
        (on.length ? '<div class="chips">' + on.map((k) => '<span class="chip">ON：' + esc(names[k] || k) + '</span>').join("") + '</div>' : "") +
        '<div class="meta">ヒント：コードは 開発者だけが しっている。…でも、答えは 意外と たんじゅん。</div></div>';
}
ACT.cGo = () => {
    const v = ($("cInput") || {}).value || ""; if(!v.trim()) return;
    const r = tqApplyCheat(v); G.cheatMsg = r.msg; G.cheatOk = r.ok; if(r.ok) flash();
    if(r.ok && G.S && G.afterCheat === "end"){ G.afterCheat = null; G.mode = "map"; rpgEnding(); return; }
    render(); const i = $("cInput"); if(i){ i.value = ""; i.focus(); }
};
ACT.cBack = () => { if(G.cheatFrom === "menu"){ G.mode = "menu"; G.menuTab = "main"; } else G.mode = "title"; render(); };

// ---------------------------------------------------------------- 入力（キーボード・タッチ）
const KEYS = {ArrowUp:"up", w:"up", W:"up", ArrowDown:"down", s:"down", S:"down", ArrowLeft:"left", a:"left", A:"left", ArrowRight:"right", d:"right", D:"right", Enter:"ok", z:"ok", Z:"ok", " ":"ok", x:"cancel", X:"cancel", Escape:"cancel", Backspace:"cancel", m:"menu", M:"menu"};
function goBack(){
    const m = G.mode;
    if(G.dlg){ ACT.dlgno(); return; }
    if(m === "slots") (G.slotPick ? ACT.slotPickCancel : ACT.slotBack)();
    else if(m === "profile") ACT.pBack(); else if(m === "persona") ACT.qBack(); else if(m === "result") ACT.rBack();
    else if(m === "help") ACT.hBack(); else if(m === "settings") ACT.sBack(); else if(m === "cheat") ACT.cBack();
    else if(m === "pack" && window.pkBack) pkBack();
    else if(m === "menu") fieldMenuBack(); else if(m === "gate") ACT.gateclose && ACT.gateclose();
    else if(m === "map") openMenu(); else if(m === "battle" && G.b && G.b.menu !== "top") { ACT.bcmd("back"); }
}
function handleKey(k, e){
    const m = G.mode;
    if(m === "pack" && window.pkKey && pkKey(k, e)) return;
    if(G.grind && !G.dlg){ stopGrind(); return; }
    if(G.dlg){ if(k === "up" || k === "left") navMove(-1); else if(k === "down" || k === "right") navMove(1); else if(k === "ok") navOk(); else if(k === "cancel") goBack(); return; }
    if(m === "map"){
        if(k === "up" || k === "down" || k === "left" || k === "right") tryMove(k);
        else if(k === "ok") fieldAct(); else if(k === "cancel" || k === "menu") openMenu();
        return;
    }
    if(m === "talk"){ if(k === "ok"){ if(!finishTyping()) rpgNext(); } else if(k === "menu") ACT.autoTalk(); return; }
    if(m === "script" || m === "end" && false) return;
    if(m === "battle" && G.auto){ if(k === "cancel" || k === "ok") ACT.bauto(); return; }
    if(k === "up" || k === "left") navMove(-1); else if(k === "down" || k === "right") navMove(1); else if(k === "ok") navOk(); else if(k === "cancel" || k === "menu") goBack();
}
document.addEventListener("keydown", (e) => {
    const tg = e.target && e.target.tagName;
    if(tg === "INPUT" || tg === "SELECT" || tg === "TEXTAREA"){
        if(e.key === "Enter"){ e.preventDefault(); if(e.target.id === "cInput") ACT.cGo(); else if(G.dlg) ACT.dlgok(); else if(e.target.id === "rpgName2") ACT.renameok(); }
        else if(e.key === "Escape" && G.dlg) ACT.dlgno();
        return;
    }
    const k = KEYS[e.key]; if(!k) return;
    if(e.ctrlKey || e.metaKey || e.altKey) return;
    e.preventDefault(); handleKey(k, e);
});
// マウスを「動かしたとき」だけ、その選択肢にカーソル（▶）をうつす。
// 止まっているマウスの下に 選択肢が 出ても、カーソルは さいしょの 選択肢のまま（3つの 真ん中に カーソルが 出る 不具合の 直し）
document.addEventListener("mousemove", (e) => {
    if(!e.movementX && !e.movementY) return;
    const b = e.target && e.target.closest && e.target.closest(".opt[data-a]"); if(!b || b.disabled || b.classList.contains("on")) return;
    const l = navList(); if(l.indexOf(b) < 0) return;
    l.forEach((x) => x.classList.remove("on")); b.classList.add("on");
});
document.addEventListener("click", (e) => {
    const a = e.target.closest("[data-a]");
    if(a && !a.disabled){ const f = ACT[a.dataset.a]; if(f){ e.preventDefault(); f(a.dataset.v, a); } return; }
    if(e.target.closest("#msg") || e.target.id === "cv"){ if(G.mode === "talk"){ if(!finishTyping()) rpgNext(); } }
});
document.addEventListener("input", (e) => {
    if(e.target.id === "pMon" || e.target.id === "pDay") { keepDraft(); const z = tqZodiac(G.draft.month, G.draft.day); const el = $("zod"); if(el) el.innerHTML = zodHtml(z); }
});
document.addEventListener("change", (e) => {
    if(e.target.id === "pMon" || e.target.id === "pDay") { keepDraft(); const z = tqZodiac(G.draft.month, G.draft.day); const el = $("zod"); if(el) el.innerHTML = zodHtml(z); }
});
// タッチボタン（長おしで連続いどう）
(function(){
    let t = null;
    const stop = () => { clearInterval(t); t = null; };
    document.addEventListener("pointerdown", (e) => {
        const b = e.target.closest && e.target.closest("#pad button"); if(!b) return;
        e.preventDefault(); const k = b.dataset.k;
        const fire = () => { if(k === "ok") handleKey("ok"); else if(k === "menu") handleKey("menu"); else handleKey(k); };
        fire(); if(k !== "ok" && k !== "menu"){ stop(); t = setInterval(fire, 150); }
    });
    ["pointerup", "pointercancel", "pointerleave"].forEach((n) => document.addEventListener(n, stop));
})();
$("btnFs").addEventListener("click", toggleFullscreen);
$("btnBgm").addEventListener("click", () => { ACT.sBgm(); });
$("btnVoice").addEventListener("click", () => { G.set.voice = !G.set.voice; if(!G.set.voice) tqSpeakStop(); tqSettingsSave(); $("btnVoice").textContent = G.set.voice ? "声：オン" : "声：オフ"; });
$("rotOk").addEventListener("click", () => document.body.classList.remove("needrot"));


/* ==== game/field.js ==== */
;(window.__AREB_S||(window.__AREB_S=[]))[12]=1;
"use strict";
// ===== フィールド：地図・いどう・会話イベント・メニュー・おみせ・ゲート =====
const TS = 32, VW = 20, VH = 11.25;
const DIRS = {up:[0, -1], down:[0, 1], left:[-1, 0], right:[1, 0]};
const cvEl = $("cv"), cx2 = cvEl.getContext("2d");

// ---------------------------------------------------------------- 地図の参照
function curMap(){ return RPG_MAPS[G.S.map]; }
function tileCh(mapId, x, y){ const r = RPG_MAPS[mapId].rows[y]; return r ? (r[x] || null) : null; }
function objVisible(o){ return (!o.hide || !rpgCond(o.hide)) && (!o.show || rpgCond(o.show)); }
function npcAt(x, y){ return (curMap().objs || []).find((o) => o.k === "npc" && o.x === x && o.y === y && objVisible(o)); }
function objAt(x, y, kind){ return (curMap().objs || []).find((o) => o.k === kind && o.x === x && o.y === y); }
function walkable(x, y){
    const ch = tileCh(G.S.map, x, y); if(!ch) return false;
    const t = RPG_TILES[ch]; if(!t || !t.w) return false;
    return !npcAt(x, y);
}
function gotoMap(map, x, y){
    const S = G.S; S.map = map; S.x = x; S.y = y; S.px = x; S.py = y; S.trail = []; G.tw = null;
    G.banner = {t:Date.now(), text:RPG_MAPS[map].name};
    const ev = RPG_ENTER[map];
    if(ev && RPG_EV[ev]) G.scripts.push({a:RPG_EV[ev], i:0});
    const tm = tqTempSync(map, false);
    if(tm.length) G.scripts.push({a:tm.map((t) => rpgN(t)), i:0});
    tqAutoSave();
}
// ---------------------------------------------------------------- いどう
function tryMove(dir){
    if(G.mode !== "map" || !G.S) return;
    const now = performance.now(), gap = G.S.cx.speed ? 70 : 125;
    if(now - (G.lastMv || 0) < gap) return; G.lastMv = now;
    if(G.info){ G.info = ""; render(); }
    moveStep(dir);
}
function moveStep(dir){
    const S = G.S, d = DIRS[dir]; if(!d) return;
    S.dir = dir;
    const nx = S.x + d[0], ny = S.y + d[1], npc = npcAt(nx, ny);
    if(npc){ talkTo(npc); return; }
    if(!walkable(nx, ny)){ paint(); return; }
    S.px = S.x; S.py = S.y;
    S.trail.unshift([S.x, S.y]); S.trail = S.trail.slice(0, 6);
    S.x = nx; S.y = ny; S.steps++;
    G.tw = {t:Date.now(), dx:-d[0], dy:-d[1]};
    afterStep();
}
function afterStep(){
    const S = G.S, mp = curMap();
    const warp = objAt(S.x, S.y, "warp");
    if(warp){
        if(warp.need && !rpgCond(warp.need)){ runScript(RPG_EV[warp.deny || "tk_locked"] || [["say", "", "いまは はいれない。"], ["back"]]); return; }
        const w = ["warp", warp.to[0], warp.to[1], warp.to[2]];
        runScript(warp.ev && RPG_EV[warp.ev] ? RPG_EV[warp.ev].concat([w]) : [w]); return;
    }
    const btn = objAt(S.x, S.y, "btn");
    if(btn && !S.wh[btn.id]){
        S.wh[btn.id] = 1; const n = 3 - Object.keys(S.wh).length;
        const steps = [["say", "", "ピッ！ とうめいな ボタンを 押した！" + (n > 0 ? "（のこり " + n + "こ）" : "（ぜんぶ 押した！）")]];
        if(n === 0){ S.f.wh_all = 1; steps.push(["say", "アナウンくん", "…あれ？ ぜんぶ 押された！？ アナウンくんの ところへ 行こう！"]); }
        runScript(steps); return;
    }
    const st = objAt(S.x, S.y, "step");
    if(st && RPG_EV[st.ev]){ runScript(RPG_EV[st.ev]); return; }
    const ch = tileCh(S.map, S.x, S.y), tev = mp.tev && mp.tev[ch];
    if(tev && tev[1] && RPG_EV[tev[0]]){ runScript(RPG_EV[tev[0]]); return; }
    if(mp.enc && !S.cx.noenc && !/[DGE]/.test(ch) && S.steps - G.lastEnc > 3 && G.rnd() < mp.enc.rate * (S.cx.encx3 ? 3 : 1)){
        G.lastEnc = S.steps; encounter(); return;
    }
    paint();
    if(G.mode === "map") updateHud();
}
function encounter(){
    const mp = curMap(), list = mp.enc.f, tot = list.reduce((a, b) => a + b[1], 0); let r = G.rnd() * tot, pick = list[0];
    for(const f of list){ r -= f[1]; if(r <= 0){ pick = f; break; } }
    battleStart(pick[0].slice(), null);
}
function fieldAct(){
    if(G.mode !== "map" || !G.S) return;
    const S = G.S, d = DIRS[S.dir], fx = S.x + d[0], fy = S.y + d[1];
    if(G.info){ G.info = ""; }
    const npc = npcAt(fx, fy);
    if(npc){ talkTo(npc); return; }
    const sign = objAt(fx, fy, "sign");
    if(sign && RPG_EV[sign.ev]){ runScript(RPG_EV[sign.ev]); return; }
    const ch = tileCh(S.map, fx, fy), mp = curMap(), tev = mp.tev && mp.tev[ch];
    if(tev && RPG_EV[tev[0]]){ runScript(RPG_EV[tev[0]]); return; }
    if(S.map === "white" && !S.f.wh_all){
        const btns = (mp.objs || []).filter((o) => o.k === "btn" && !S.wh[o.id]);
        if(btns.length){
            const dist = Math.min(...btns.map((b) => Math.abs(b.x - S.x) + Math.abs(b.y - S.y)));
            runScript([["say", "", dist <= 2 ? "ぴりぴり…！ すぐ ちかくに ボタンが ある 気が する！" : dist <= 5 ? "なにか ちかくに ある 気が する…" : "…とおい。この あたりには なさそうだ。"]]); return;
        }
    }
    render();
}
function talkTo(npc){
    const S = G.S; G.npcDir[npc.id] = {up:"down", down:"up", left:"right", right:"left"}[S.dir];
    const ev = RPG_EV[npc.ev]; if(ev) runScript(ev);
}
// ---------------------------------------------------------------- 会話イベントの実行
function runScript(steps){
    if(!steps) return;
    G.scripts.push({a:steps, i:0});
    if(G.mode === "map" || G.mode === "script" || G.mode === "menu" || G.mode === "shop" || G.mode === "gate"){ G.mode = "script"; pump(); }
}
function rpgNext(){ if(G.mode === "talk"){ tqSpeakStop(); pump(); } }
function pump(){
    const st = G.scripts, S = G.S;
    for(let guard = 0; guard < 5000; guard++){
        const fr = st[st.length - 1];
        if(!fr){ if(window.pkPumpEnd && pkPumpEnd()) return; G.mode = "map"; G.say = null; tqAutoSave(); render(); paint(); return; }
        if(fr.i >= fr.a.length){ st.pop(); continue; }
        const op = fr.a[fr.i++], k = op[0];
        if(k === "say"){ G.mode = "talk"; G.say = {who:(window.tqWho ? tqWho(op[1]) : op[1]), text:(window.tqRen ? tqRen(rpgFmt(op[2])) : rpgFmt(op[2]))}; tqSpeak(G.say.text, op[1]); render(); return; }
        if(k === "choice"){ G.mode = "choice"; G.choices = op[1]; render(); return; }
        if(k === "set") S.f[op[1]] = 1;
        else if(k === "clr") delete S.f[op[1]];
        else if(k === "if"){ const br = rpgCond(op[1]) ? op[2] : op[3]; if(br && br.length) st.push({a:br, i:0}); }
        else if(k === "run"){ if(RPG_EV[op[1]]) st.push({a:RPG_EV[op[1]], i:0}); }
        else if(k === "pick"){ const l = op[1]; st.push({a:l[Math.floor(G.rnd() * l.length) % l.length], i:0}); }
        else if(k === "warp") gotoMap(op[1], op[2], op[3]);
        else if(k === "back"){ S.x = S.px; S.y = S.py; G.tw = null; }
        else if(k === "gold") S.gold = Math.min(TQ_MAX_GOLD, S.gold + op[1]);
        else if(k === "item") S.items[op[1]] = (S.items[op[1]] || 0) + (op[2] || 1);
        else if(k === "mem") S.mem[op[1] - 1] = 1;
        else if(k === "join"){ if(!tqAddMember(op[1], false)) S.f["full_" + op[1]] = 1; }
        else if(k === "heal") tqHealAll();
        else if(k === "bg"){ G.bg = op[1] || ""; }
        else if(k === "flash") flash();
        else if(k === "battle"){ battleStart(op[1].slice(), op[2]); return; }
        else if(k === "shop"){ G.mode = "shop"; G.shopMsg = ""; render(); return; }
        else if(k === "gate"){ G.mode = "gate"; render(); return; }
        else if(k === "rename"){ G.mode = "rename"; render(); return; }
        else if(k === "recap") st.push({a:recapSteps(), i:0});
        else if(k === "end"){ rpgEnding(); return; }
        else if(k === "pkev"){ if(window.pkEvSeen) pkEvSeen(op[1]); }
        else if(k === "pkcall"){ if(typeof op[1] === "string" && /^pk[A-Za-z]+$/.test(op[1]) && typeof window[op[1]] === "function") window[op[1]](op[2]); }
    }
    G.mode = "map"; render();
}
// 会話スキップ：えらぶ場面・戦闘・ショップなどで止まる。ふくしゅうは しない（1つずつ とばす）
ACT.skipTalk = () => {
    let guard = 0; finishTyping();
    while(G.mode === "talk" && guard++ < 400){ tqSpeakStop(); pump(); }
};
ACT.next = () => { if(!finishTyping()) rpgNext(); };
ACT.choose = (v) => {
    if(G.mode !== "choice" || !G.choices) return;
    const c = G.choices[Number(v)]; G.choices = null; G.mode = "script";
    if(c) G.scripts.push({a:c[1], i:0});
    pump();
};
function recapSteps(){
    const f = G.S.f, L = [["say", "", "ここまでの おはなし。メモリは " + tqMemCount() + "/6 こ。"]];
    [["e_sendai", "ホシミ台で 迷惑ボーイ 玲也の ノイズを おとなしくさせ、ひかりのメモリを 取りもどした。"], ["e_tokyo", "夜の アカリ市で 蒼太さんを はげまし、さえこと コピペ・パンダを 説得して メモリを 手に入れた。"],
        ["e_white", "まっしろルームで『みんなで クリア』の ルールを 取りもどした。"], ["e_xmas", "クリスマスの アカリ市で 紘と いっしょに USBメモリを 取りかえした。"], ["e_labn", "ARE が 生まれた 夜の 研究室で 設計図を もらった。"]].forEach((p) => { if(f[p[0]]) L.push(["say", "", p[1]]); });
    if(!f.e_sendai) L.push(["say", "", "まだ 旅は はじまったばかり。ゲートから ホシミ台へ 行こう。"]);
    if(f.e_future) L.push(["say", "", "そして 2035年。ノイズの 王は ARE の マスコットに なった。ARE は 完成した！"]);
    else if(f.e_n11) L.push(["say", "", "ノイズの 深層を しずめた。のこりは さいごの メモリ。2035年の ARE タワーへ。"]);
    else if(f.e_labn) L.push(["say", "", "つぎは『ノイズの深層』。ゲートの 新しい 行き先へ。"]);
    return L;
}
function tqObjective(){
    const f = G.S.f;
    if(!f.intro_done) return "ラボの アキトと ハルキに 話しかけよう";
    if(!f.e_sendai) return f.sn_ready ? "AER展望台（北の階段の先）で 玲也の ノイズを おとなしくさせよう" : "2026年9月の ホシミ台で 手がかりを あつめよう（駅員さん・牛タン屋さん・亜理紗）";
    if(!f.e_tokyo) return "ゲートから 2025年12月の 夜のアカリ市へ。蒼太さんを たずねよう";
    if(!f.e_white) return "『まっしろルーム』へ。透明ボタンを 3つ さがそう";
    if(!f.e_xmas) return "2028年12月25日の クリスマスのアカリ市へ。紘に 会おう";
    if(!f.e_labn) return "ARE が 生まれた 夜へ。若い アキトと ハルキに 会おう";
    if(!f.e_n8) return "『ノイズの深層』へ。ゲートに 新しい 行き先が ひらいたよ（推奨 Lv28）";
    if(!f.e_n9) return "第2層『ノイズの海ぞこ』へ。ぬしの ミラを たすけよう（推奨 Lv33）";
    if(!f.e_n10) return "第3層『くものうえの サーバー城』へ（推奨 Lv38）";
    if(!f.e_n11) return "第4層『ノイズ王国 さいおくぶ』で ノイズ・オメガと たたかおう（推奨 Lv43）";
    if(!f.e_future) return "のこりの メモリは 2035年の ARE タワー。ノイズの 王が いる！（さいごの たたかい）";
    if(!f.xr_open) f.xr_open = 1;
    if(!f.e_ep10) return "追加エピソード：2026年10月『ウォークラリーと がけ』へ（ゲート）";
    if(!f.e_ep11) return "追加エピソード：2026年11月21日『おんがくの はくぶつかん』へ（ゲート）";
    if(!f.e_ep11b) return "追加エピソード：2026年11月22日『おおそうじと となりの さわぎ』へ（ゲート）";
    if(!f.e_ep12) return "追加エピソード：2026年12月『キラキラ ラウンジの わな』へ（ゲート）";
    if(!f.e_ep01) return "追加エピソード：2027年1月『22さいへの みち』へ（ゲート）";
    if(!f.e_ks1) return "追加：烏坂探偵事務所① 1〜4話『うらない師と マジックの なぞ』へ（ゲート）。なぞは えらんで とくだけ！";
    if(!f.e_ks2) return "追加：烏坂探偵事務所② 5〜10話『ニセテストの なぞ』へ（ゲート）";
    if(!f.e_ks3) return "追加：烏坂探偵事務所③ 11〜15話『マジックショーと てがみ』へ（ゲート）";
    if(!f.e_ks4) return "追加：烏坂探偵事務所④ 16〜20話・最終話『さいごの マジック』へ（ゲート）";
    if(!f.e_ks5) return "追加：烏坂探偵事務所⑤ SP『丹羽鳥島の ひみつ』へ（ゲート）";
    if(!f.e_xr) return "クリア おめでとう！ おまけ：『XRアドベンチャー体験会』へ（ゲート）";
    return "ぜんぶ クリア！『自動レベル上げ』で レベル99を めざそう";
}
function rpgEnding(){
    G.mode = "end"; G.scripts.length = 0; G.bg = ""; G.S.f.xr_open = 1;
    const S = G.S;
    G.endText = rpgFmt("{名前}は ARE を 完成させた！\nノイズだった ものは、いま ARE の やさしい マスコットに。\nそして 今日も どこかで だれかが つぶやく。\n「そうだ！ そういうときは、AREだ！」\n\n（歩数 " + S.steps + "・たおした数 " + S.kills + "・レベル " + S.lv + "・プレイ " + tqPlayText(S.play) + "）\n\n★ おまけ『XRアドベンチャー体験会』が ゲートに ひらいたよ！");
    G.endT0 = Date.now(); G.endBgm = true;
    tqSpeak("そうだ！ そういうときは、AREだ！", "アキト");
    tqAutoSave(); render();
}
ACT.endback = () => { G.mode = "script"; G.scripts = []; tqHealAll(); gotoMap("lab", 8, 8); pump(); };

// ---------------------------------------------------------------- 画面のHTML（フィールド系）
function hudHtml(){
    const S = G.S;
    const lines = S.party.map((id) => { const st = tqStat(id), m = S.m[id]; return '<div class="l' + (m.hp <= 0 ? " ko" : "") + '">' + esc(tqName(id)) + ' Lv' + S.lv + ' HP ' + m.hp + '/' + st.maxhp + ' MP ' + m.mp + '/' + st.maxmp + '</div>'; }).join("");
    let zone = ""; try{
        const mp = curMap(), ch = tileCh(S.map, S.x, S.y), danger = !!(mp && mp.enc && !S.cx.noenc && !/[DGE]/.test(ch));
        zone = danger ? '<br><b style="color:#ff9a8a">⚔ ここは モンスターが出る場所</b>' : '<br><b style="color:#8fe8a8">🕊 ここは モンスターが出ない場所</b>';
    }catch(_e){}
    return '<div id="hud" class="win">' + lines + '</div><div id="hudr" class="win">💰' + S.gold.toLocaleString() + 'G　メモリ ' + tqMemCount() + '/6' + (G.grind ? '<br>⚡れんぞく戦闘 ' + G.grind.n + '回' : "") + (S.cx.showpos ? '<br>(' + S.x + ',' + S.y + ')' : "") + zone + '</div>';
}
function updateHud(){ const h = $("hud"); if(h && G.mode === "map"){ const d = document.createElement("div"); d.innerHTML = hudHtml(); h.innerHTML = d.firstChild.innerHTML; const r = $("hudr"); if(r) r.innerHTML = d.lastChild.innerHTML; } }
function fieldView(){
    const m = G.mode, S = G.S; let h = "";
    if(!S) return "";
    if(m === "battle") return battleView();
    if(m === "map" || m === "talk" || m === "choice" || m === "script") h += hudHtml();
    if(m === "talk") h += winMsg(G.say.who, G.say.text) + tqAutoBtnHtml() + '<button class="btn sub" id="skipBtn" data-a="skipTalk" style="position:absolute;right:2cqw;top:6.8cqw;z-index:5">⏭ スキップ</button>';
    else if(m === "choice"){
        h += (G.say ? winMsg(G.say.who, G.say.text, {next:false}) : "") + '<div id="choices" class="win">' + (G.choices || []).map((c, i) => '<button class="opt" data-a="choose" data-v="' + i + '">' + esc(rpgFmt(c[0])) + '</button>').join("") + '</div>';
    }
    else if(m === "map" && G.info) h += winMsg("", G.info, {next:false});
    else if(m === "menu") h += menuView();
    else if(m === "shop") h += shopView();
    else if(m === "gate") h += gateView();
    else if(m === "rename") h += renameView();
    else if(m === "end") h += creditsHtml();
    return h;
}
// ---- おみせ ----
function shopView(){
    const S = G.S;
    const row = (id) => {
        const it = RPG_ITEMS[id] || RPG_EQUIP[id], eq = RPG_EQUIP[id], have = eq ? S.own.includes(id) : (S.items[id] || 0);
        const desc = eq ? ({w:"こうげき", a:"ぼうぎょ", c:"ぼうぎょ"}[eq.slot] + "+" + eq.v) : it.d;
        return '<div class="card row" style="justify-content:space-between"><span><b>' + esc(it.n) + '</b> <span class="meta">' + esc(desc || "") + (eq ? "" : "（もっている " + have + "）") + '</span></span>' +
            (eq && have ? '<span class="meta">' + (S.eq[eq.slot] === id ? "そうびちゅう" : "もっている") + '</span>' : '<button class="btn' + (S.gold < it.price ? " sub" : "") + '" data-a="buy" data-v="' + id + '">' + it.price + 'G</button>') + '</div>';
    };
    return winMsg("ミナ", G.shopMsg || "いらっしゃいませ！ 何に します？", {next:false}).replace('id="msg"', 'id="msg" style="left:30cqw"') +
        '<div class="win panel scroll" style="left:28cqw;top:2cqw;transform:none;width:68cqw;max-height:calc(100cqh - 27cqw)"><div class="meta">所持金：' + S.gold.toLocaleString() + 'G</div>' + rpgShopStock(tqMemCount()).map(row).join("") + '<div class="row" style="margin-top:.6cqw"><button class="btn sub" data-a="shopclose">店を 出る</button></div></div>';
}
function buyItem(id){
    const S = G.S, def = RPG_ITEMS[id] || RPG_EQUIP[id]; if(!def) return "";
    if(S.gold < def.price) return "ゴールドが たりない！";
    if(RPG_EQUIP[id]){ const e = RPG_EQUIP[id]; if(S.own.includes(id)) return "もう もっている！"; S.gold -= def.price; S.own.push(id); if(e.v >= RPG_EQUIP[S.eq[e.slot]].v) S.eq[e.slot] = id; tqClamp(); return e.n + "を かった！" + (S.eq[e.slot] === id ? "（そうびした）" : ""); }
    if((S.items[id] || 0) >= 99) return "これいじょう もてない！";
    S.gold -= def.price; S.items[id] = (S.items[id] || 0) + 1; return def.n + "を かった！";
}
ACT.buy = (v) => { G.shopMsg = buyItem(v); tqAutoSave(); render(); };
ACT.shopclose = () => { G.shopMsg = ""; G.mode = "script"; pump(); };
// ---- ゲート ----
function eraList(){ const S = G.S; return RPG_ERAS.filter((e) => S.cx.allgate || rpgCond(e.req)); }
function gateView(){
    const S = G.S;
    return winMsg("リプレイゲート", "行き先を えらんでください。", {next:false}) + '<div class="win" id="choices" style="right:3cqw;bottom:19cqw;max-width:60cqw">' + eraList().map((e) => '<button class="opt" data-a="era" data-v="' + e.id + '">' + (S.f[e.done] ? "✅ " : "▶ ") + esc(e.n) + '</button>').join("") + '<button class="opt" data-a="gateclose">やめる</button></div>';
}
ACT.gateclose = () => { G.mode = "map"; G.scripts.length = 0; G.say = null; render(); };
ACT.era = (v) => { const e = RPG_ERAS.find((x) => x.id === v); if(!e) return; G.scripts.length = 0; G.mode = "script"; gotoMap(e.map, e.pos[0], e.pos[1]); pump(); };
// ---- なまえ変更 ----
function renameView(){ return winMsg("", "なまえを かえます。（10文字まで）", {next:false}) + '<div class="win panel sm" style="top:35%"><label for="rpgName2">あたらしい なまえ</label><input id="rpgName2" type="text" maxlength="10" value="' + esc(G.S.name) + '" style="width:100%"><div class="row" style="margin-top:.8cqw"><button class="btn" data-a="renameok">けってい</button><button class="btn sub" data-a="renamecancel">やめる</button></div></div>'; }
ACT.renameok = () => { const v = Array.from((($("rpgName2") || {}).value || "").trim()).slice(0, 10).join(""); if(v){ G.S.name = v; } tqAutoSave(); if(G.scripts.length){ G.mode = "script"; pump(); } else { G.mode = "map"; G.info = rpgFmt("なまえを {名前} に かえた。"); render(); } };
ACT.renamecancel = () => { if(G.scripts.length){ G.mode = "script"; pump(); } else { G.mode = "map"; render(); } };

// ---------------------------------------------------------------- メニュー
function openMenu(){ if(G.mode !== "map") return; G.mode = "menu"; G.menuTab = "main"; G.menuMsg = ""; render(); }
function fieldMenuBack(){ if(G.menuTab && G.menuTab !== "main"){ G.menuTab = "main"; render(); } else { G.mode = "map"; tqAutoSave(); render(); } }
ACT.mclose = () => { G.mode = "map"; tqAutoSave(); render(); };
function menuView(){
    const S = G.S, t = G.menuTab || "main";
    const left = '<div id="mm" class="win">' + [["status", "ステータス"], ["items", "どうぐ"], ["equip", "そうび"], ["mem", "メモリ・もくてき"], ["auto", "⚡ じどう（オート）"], ["pack", "🎪 追加コンテンツ"], ["job", "👔 てんしょく"], ["title", "🏅 しょうごう"], ["guide", "❓ こまったときは"], ["custom", "🔧 なまえ・むずかしさ"], ["save", "📖 ぼうけんのしょ"], ["cheat", "🔑 チート"], ["settings", "せってい"], ["help", "あそびかた"]].map((x) => '<button class="opt" data-a="mnav" data-v="' + x[0] + '">' + x[1] + '</button>').join("") + '<button class="opt" data-a="mclose">とじる</button></div>';
    let body = "";
    if(t === "main"){
        body = '<h2>' + esc(S.name) + ' たち</h2>' + (window.tqTitleNow && tqTitleNow() ? '<div class="meta">🏅『' + esc(tqTitleNow()) + '』</div>' : '') + S.party.map((id) => { const st = tqStat(id), m = S.m[id]; return '<div class="card"><b>' + esc(tqName(id)) + '</b> Lv' + S.lv + '　HP ' + m.hp + '/' + st.maxhp + '　MP ' + m.mp + '/' + st.maxmp + '</div>'; }).join("") +
            '<div class="card"><b>🎯 いまの もくてき</b><div>' + esc(tqObjective()) + '</div></div><div class="meta">💰' + S.gold.toLocaleString() + 'G　プレイ ' + tqPlayText(S.play) + '　' + esc(curMap().name) + '</div>';
    }else if(t === "status"){
        const pr = S.prof || {};
        body = '<h2>ステータス</h2>' + S.party.map((id) => { const st = tqStat(id), m = S.m[id]; return '<div class="card"><b>' + esc(tqName(id)) + '</b> Lv' + S.lv + '<div class="meta">HP ' + m.hp + '/' + st.maxhp + '　MP ' + m.mp + '/' + st.maxmp + '　こうげき ' + st.atk + '　ぼうぎょ ' + st.def + '　すばやさ ' + st.agi + '</div></div>'; }).join("") +
            '<div class="card meta">つぎの レベルまで あと ' + (S.lv >= TQ_MAX_LV ? "—（最大）" : (rpgNeed(S.lv) - S.exp) + "EXP") + '　たおした数 ' + S.kills + '　歩数 ' + S.steps + (S.expmul > 1 ? "　経験値 ×" + S.expmul : "") + '</div>' +
            (pr.zodiac ? '<div class="card meta">' + pr.zodiac.mark + ' ' + esc(pr.zodiac.name) + '　性格：' + esc(pr.pers ? pr.pers.name : "—") + '</div>' : "");
    }else if(t === "items"){
        const l = Object.keys(RPG_ITEMS).filter((k) => S.items[k] > 0);
        body = '<h2>どうぐ</h2>' + (l.length ? l.map((k) => '<div class="card"><b>' + esc(RPG_ITEMS[k].n) + '</b>×' + S.items[k] + ' <span class="meta">' + esc(RPG_ITEMS[k].d || "") + '</span><div class="row">' + S.party.map((id) => '<button class="btn sub" data-a="use" data-v="' + k + '|' + id + '">' + esc(tqName(id)) + 'に</button>').join("") + '</div></div>').join("") : '<div class="meta">どうぐは ありません</div>') + (G.menuMsg ? '<div class="okc">' + esc(G.menuMsg) + '</div>' : "");
    }else if(t === "equip"){
        body = '<h2>そうび</h2>' + ["w", "a", "c"].map((slot) => '<div class="card"><b>' + ({w:"ぶき", a:"ぼうぐ", c:"おまもり"}[slot]) + '</b><div class="row">' + S.own.filter((id) => RPG_EQUIP[id].slot === slot).map((id) => '<button class="btn' + (S.eq[slot] === id ? "" : " sub") + '" data-a="equip" data-v="' + id + '">' + esc(RPG_EQUIP[id].n) + '(+' + RPG_EQUIP[id].v + ')</button>').join("") + '</div></div>').join("");
    }else if(t === "mem"){
        body = '<h2>メモリ・もくてき</h2><div class="card"><b>🎯 もくてき</b><div>' + esc(tqObjective()) + '</div></div>' + RPG_MEM_NAMES.map((n, i) => '<div class="card">' + (S.mem[i] ? "✅ " : "⬜ ") + esc(rpgFmt(n)) + '</div>').join("");
    }else if(t === "title"){
        body = window.tqTitleView ? tqTitleView() : "";
    }else if(t === "guide"){
        body = window.tqGuideView ? tqGuideView() : "";
    }else if(t === "job"){
        body = window.tqJobView ? tqJobView() : "";
    }else if(t === "custom"){
        body = window.tqCustomView ? tqCustomView() : "";
    }else if(t === "auto"){
        body = '<h2>⚡ じどう（オート）</h2><div class="card"><b>オート戦闘：' + (G.autoPref ? "ON" : "OFF") + '</b><div class="meta">ONに すると、戦闘が 自動で すすみます。戦闘中の ボタンでも 切りかえ できます。</div><div class="row"><button class="btn" data-a="autoPref">オート戦闘を ' + (G.autoPref ? "OFF" : "ON") + ' に する</button></div></div>' +
            '<div class="card"><b>れんぞく戦闘（自動レベル上げ）</b><div class="meta">いまの 地図で、敵と 自動で たたかいつづけます。HPが 少なくなると おにぎりを つかい、足りなければ ストップ。' + (curMap().enc ? "" : "<br>※ この場所では できません（敵の出る場所へ いこう）") + '</div><div class="row"><button class="btn" data-a="grindStart"' + (curMap().enc ? "" : " disabled") + '>▶ スタート</button></div></div>' + (G.menuMsg ? '<div class="okc">' + esc(G.menuMsg) + '</div>' : "");
    }
    return left + '<div id="mc" class="win">' + body + '</div>';
}
ACT.mnav = (v) => {
    if(v === "save"){ G.slotCtx = "save"; G.slotFrom = "menu"; G.slotPick = null; G.mode = "slots"; render(); return; }
    if(v === "pack"){ if(window.pkOpenHub) pkOpenHub("menu"); return; }
    if(v === "cheat"){ G.cheatFrom = "menu"; G.cheatMsg = ""; G.mode = "cheat"; render(); return; }
    if(v === "settings"){ G.setFrom = "menu"; G.mode = "settings"; render(); return; }
    if(v === "help"){ G.helpFrom = "menu"; G.mode = "help"; render(); return; }
    G.menuTab = v; G.menuMsg = ""; render();
};
ACT.use = (v) => { const [k, id] = v.split("|"); G.menuMsg = useItem(k, id); tqAutoSave(); render(); };
ACT.equip = (v) => { const e = RPG_EQUIP[v]; if(e && G.S.own.includes(v)){ G.S.eq[e.slot] = v; tqClamp(); tqAutoSave(); render(); } };
function useItem(id, to){
    const S = G.S, it = RPG_ITEMS[id]; if(!it || !S.items[id]) return "もっていない！";
    const mm = S.m[to], mx = tqStat(to);
    if(it.revive){ if(mm.hp > 0) return "たおれて いない！"; S.items[id]--; mm.hp = Math.ceil(mx.maxhp / 2); return tqName(to) + "は ふっかつした！"; }
    if(mm.hp <= 0) return "たおれていて つかえない！";
    if(it.hp){ if(mm.hp >= mx.maxhp) return "HPは まんたん だ！"; S.items[id]--; const b = mm.hp; mm.hp = Math.min(mx.maxhp, mm.hp + it.hp); return tqName(to) + "の HPが " + (mm.hp - b) + " かいふく！"; }
    if(it.mp){ if(mm.mp >= mx.maxmp) return "MPは まんたん だ！"; S.items[id]--; const b = mm.mp; mm.mp = Math.min(mx.maxmp, mm.mp + it.mp); return tqName(to) + "の MPが " + (mm.mp - b) + " かいふく！"; }
    return "";
}

// ---------------------------------------------------------------- ゲーム開始
function enterGame(msg){
    G.mode = "map"; G.bg = ""; G.say = null; G.info = msg || "";
    const outs = tqFlushCheatQueue();
    if(outs.length) G.info = (G.info ? G.info + "\n" : "") + outs.join("\n");
    G.banner = {t:Date.now(), text:curMap().name};
    if(G.afterCheat === "end"){ G.afterCheat = null; rpgEnding(); return; }
    render(); paint();
}

// ---------------------------------------------------------------- 絵（ドット絵ふうの描画）
function rng(x, y, n){ return (((x * 73856093) ^ (y * 19349663)) >>> 0) % n; }
function rr(g, x, y, w, h, r){ g.beginPath(); if(g.roundRect) g.roundRect(x, y, w, h, r); else g.rect(x, y, w, h); g.fill(); }
function drawTile(g, ch, X, Y, tx, ty, time){
    const t = RPG_TILES[ch] || RPG_TILES["."], S = TS;
    g.fillStyle = t.c; g.fillRect(X, Y, S, S);
    const r = rng(tx, ty, 8);
    switch(t.d){
        case "tuft": g.fillStyle = "rgba(30,110,50,.35)"; g.fillRect(X + 6 + r * 2, Y + 8 + (r % 3) * 6, 2, 4); g.fillRect(X + 20 - r, Y + 18 + (r % 2) * 5, 2, 4); break;
        case "path": g.fillStyle = "rgba(140,100,50,.25)"; g.fillRect(X + 5 + r * 3, Y + 6 + (r % 4) * 6, 3, 2); g.fillRect(X + 18, Y + 20 - (r % 3) * 4, 3, 2); break;
        case "wave": { g.fillStyle = "rgba(255,255,255,.35)"; const o = Math.floor(time / 300 + tx) % 4; g.fillRect(X + 4 + o * 2, Y + 8, 10, 2); g.fillRect(X + 14 - o * 2, Y + 20, 10, 2); break; }
        case "brick": g.strokeStyle = "rgba(0,0,0,.28)"; g.strokeRect(X + .5, Y + .5, S - 1, S / 2); g.strokeRect(X + .5, Y + S / 2 + .5, S - 1, S / 2 - 1); break;
        case "plank": g.fillStyle = "rgba(120,80,30,.22)"; g.fillRect(X, Y + 10, S, 1); g.fillRect(X, Y + 21, S, 1); break;
        case "carpet": g.strokeStyle = "rgba(255,230,160,.5)"; g.strokeRect(X + 2.5, Y + 2.5, S - 5, S - 5); break;
        case "window": g.fillStyle = "rgba(255,255,255,.55)"; g.fillRect(X + 3, Y + 3, S - 6, 3); g.fillRect(X + S / 2 - 1, Y + 3, 2, S - 6); g.fillRect(X + 3, Y + S / 2, S - 6, 2); break;
        case "snow": g.fillStyle = "rgba(160,190,230,.5)"; g.fillRect(X + 6 + r * 2, Y + 10, 2, 2); g.fillRect(X + 20, Y + 22 - (r % 3) * 4, 2, 2); break;
        case "grid": g.strokeStyle = "rgba(0,0,0,.07)"; g.strokeRect(X + .5, Y + .5, S, S); break;
        case "gate": { const a = 0.35 + 0.25 * Math.sin(time / 260 + tx); g.fillStyle = "rgba(120,220,255," + a + ")"; g.beginPath(); g.arc(X + S / 2, Y + S / 2, 13, 0, 7); g.fill(); g.strokeStyle = "rgba(255,255,255,.8)"; g.beginPath(); g.arc(X + S / 2, Y + S / 2, 8 + 3 * Math.sin(time / 200), 0, 5); g.stroke(); break; }
        case "bldg": g.fillStyle = "rgba(255,230,120,.85)"; for(let i = 0; i < 2; i++) for(let j = 0; j < 2; j++) if(rng(tx + i, ty + j, 3) > 0) g.fillRect(X + 4 + i * 14, Y + 5 + j * 14, 8, 8); break;
        case "roof": g.fillStyle = "rgba(0,0,0,.18)"; g.fillRect(X, Y + 8, S, 2); g.fillRect(X, Y + 20, S, 2); break;
        case "wall": g.fillStyle = "rgba(0,0,0,.08)"; g.fillRect(X, Y + S - 4, S, 4); break;
        case "stone": g.strokeStyle = "rgba(0,0,0,.14)"; g.strokeRect(X + .5, Y + .5, S, S); break;
        case "tech": g.fillStyle = "rgba(120,160,220,.25)"; g.fillRect(X, Y + 15, S, 2); break;
        case "glass": g.fillStyle = "rgba(255,255,255,.55)"; g.beginPath(); g.moveTo(X + 6, Y + S); g.lineTo(X + 16, Y); g.lineTo(X + 22, Y); g.lineTo(X + 12, Y + S); g.fill(); break;
        case "server": g.fillStyle = (Math.floor(time / 350) + tx + ty) % 3 === 0 ? "#34d399" : "#38bdf8"; g.fillRect(X + 6, Y + 6, 3, 3); g.fillRect(X + 6, Y + 14, 3, 3); g.fillRect(X + 6, Y + 22, 3, 3); g.fillStyle = "rgba(255,255,255,.18)"; g.fillRect(X + 14, Y + 6, 12, 3); g.fillRect(X + 14, Y + 14, 12, 3); g.fillRect(X + 14, Y + 22, 12, 3); break;
        case "ice": g.fillStyle = "rgba(255,255,255,.55)"; g.fillRect(X + 4, Y + 6, 10, 2); g.fillRect(X + 16, Y + 18, 9, 2); break;
        case "nroad": g.fillStyle = "rgba(255,255,255,.1)"; if(ty % 4 === 0) g.fillRect(X + 4, Y + 15, 10, 2); break;
        default: break;
    }
    if(t.e){ g.font = "24px serif"; g.textAlign = "center"; g.textBaseline = "middle"; g.fillStyle = "#000"; g.fillText(t.e, X + S / 2, Y + S / 2 + 2); }
}
function rpgSprite(g, look, px, py, dir, bob, sec, rainbow){
    const L = RPG_LOOKS[look] || RPG_LOOKS.citizen, cx = px + 16, b = bob || 0, up = dir === "up";
    if(rainbow) g.save(), g.filter = "hue-rotate(" + (Date.now() / 6 % 360) + "deg) saturate(1.6)";
    g.fillStyle = "rgba(0,0,0,.22)"; g.beginPath(); g.ellipse(cx, py + 29, 9, 3.5, 0, 0, 7); g.fill();
    const step = sec ? (Math.floor(sec) % 2) : 0;
    g.fillStyle = L.bot; g.fillRect(cx - 6, py + 22 + b, 5, 7 - (step ? 1 : 0)); g.fillRect(cx + 1, py + 22 + b, 5, 7 - (step ? 0 : 1));
    g.fillStyle = L.top; rr(g, cx - 8, py + 12 + b, 16, 12, 3);
    g.fillRect(cx - 11, py + 13 + b, 3, 9); g.fillRect(cx + 8, py + 13 + b, 3, 9);
    g.fillStyle = L.skin; g.fillRect(cx - 11, py + 21 + b, 3, 2); g.fillRect(cx + 8, py + 21 + b, 3, 2);
    if(L.acc === "tie"){ g.fillStyle = "#d62828"; g.fillRect(cx - 1.5, py + 13 + b, 3, 7); }
    if(L.acc === "scarf"){ g.fillStyle = "#d33"; g.fillRect(cx - 7, py + 15 + b, 14, 3); }
    g.fillStyle = L.skin; g.beginPath(); g.arc(cx, py + 9 + b, 8, 0, 7); g.fill();
    g.fillStyle = L.hair;
    const hy = py + 8 + b;
    if(L.style !== "bald"){
        if(up){ g.beginPath(); g.arc(cx, py + 9 + b, 8.6, 0, 7); g.fill(); }
        else{ g.beginPath(); g.arc(cx, hy, 8.6, Math.PI, 2 * Math.PI); g.fill(); g.fillRect(cx - 8.6, hy, 3, 3); g.fillRect(cx + 5.6, hy, 3, 3); }
        if(L.style === "spike"){ g.beginPath(); g.moveTo(cx - 8, hy - 2); g.lineTo(cx - 5, hy - 12); g.lineTo(cx - 1, hy - 5); g.lineTo(cx + 3, hy - 13); g.lineTo(cx + 6, hy - 5); g.lineTo(cx + 9, hy - 10); g.lineTo(cx + 8, hy - 1); g.fill(); }
        if(L.style === "long"){ g.fillRect(cx - 9.5, hy - 1, 4, 16); g.fillRect(cx + 5.5, hy - 1, 4, 16); }
        if(L.style === "bob"){ g.fillRect(cx - 9.5, hy - 1, 4, 9); g.fillRect(cx + 5.5, hy - 1, 4, 9); }
        if(L.style === "twin"){ g.beginPath(); g.arc(cx - 11, hy + 3, 3.5, 0, 7); g.arc(cx + 11, hy + 3, 3.5, 0, 7); g.fill(); }
        if(L.style === "bun"){ g.beginPath(); g.arc(cx, hy - 8, 4, 0, 7); g.fill(); }
        if(L.style === "cap"){ g.fillStyle = L.top; g.beginPath(); g.arc(cx, hy, 8.8, Math.PI, 2 * Math.PI); g.fill(); g.fillRect(cx - 10, hy - 1, 20, 2.5); }
    }
    if(!up){
        const ox = dir === "left" ? -2 : dir === "right" ? 2 : 0;
        g.fillStyle = "#1a1a1a"; g.fillRect(cx - 4 + ox, py + 9 + b, 2, 3); g.fillRect(cx + 2 + ox, py + 9 + b, 2, 3);
        g.fillStyle = "rgba(255,120,120,.5)"; g.fillRect(cx - 6 + ox, py + 13 + b, 3, 2); g.fillRect(cx + 3 + ox, py + 13 + b, 3, 2);
        if(L.acc === "glasses"){ g.strokeStyle = "#222"; g.lineWidth = 1; g.strokeRect(cx - 6 + ox, py + 8 + b, 5, 5); g.strokeRect(cx + 1 + ox, py + 8 + b, 5, 5); }
        if(L.acc === "xr"){ g.fillStyle = "rgba(60,200,255,.85)"; g.fillRect(cx - 7 + ox, py + 8 + b, 14, 4); }
    }
    if(L.acc === "santa"){ g.fillStyle = "#d62828"; g.beginPath(); g.moveTo(cx - 8, hy); g.lineTo(cx + 1, py - 7 + b); g.lineTo(cx + 8, hy); g.fill(); g.fillStyle = "#fff"; g.fillRect(cx - 9, hy - 2, 18, 3); g.beginPath(); g.arc(cx + 1, py - 7 + b, 3, 0, 7); g.fill(); }
    if(rainbow) g.restore();
}
function paint(){
    const g = cx2, S = G.S, time = Date.now();
    g.setTransform(2, 0, 0, 2, 0, 0);
    if(G.mode === "battle" && G.b){ paintBattle(g, time); return; }
    if(!S || !RPG_MAPS[S.map]) return;
    g.fillStyle = "#0b1020"; g.fillRect(0, 0, 640, 360);
    const mp = curMap(), W = mp.rows[0].length, H = mp.rows.length;
    let fx = S.x, fy = S.y;
    if(G.tw){ const t = Math.min(1, (time - G.tw.t) / 120); fx += G.tw.dx * (1 - t); fy += G.tw.dy * (1 - t); if(t >= 1) G.tw = null; }
    const camX = W <= VW ? -(VW - W) / 2 : Math.max(0, Math.min(W - VW, fx - VW / 2 + 0.5));
    const camY = H <= VH ? -(VH - H) / 2 : Math.max(0, Math.min(H - VH, fy - VH / 2 + 0.5));
    for(let ty = Math.floor(camY) - 1; ty <= camY + VH + 1; ty++) for(let tx = Math.floor(camX) - 1; tx <= camX + VW + 1; tx++){
        const ch = tileCh(S.map, tx, ty); if(!ch) continue;
        drawTile(g, ch, Math.round((tx - camX) * TS), Math.round((ty - camY) * TS), tx, ty, time);
    }
    (mp.objs || []).forEach((o) => { if(o.k === "btn" && S.wh[o.id]){ g.fillStyle = "rgba(80,170,255,.65)"; g.beginPath(); g.arc((o.x - camX) * TS + 16, (o.y - camY) * TS + 16, 9, 0, 7); g.fill(); } });
    const items = [];
    (mp.objs || []).forEach((o) => { if(o.k === "npc" && objVisible(o)) items.push({y:o.y, f:() => rpgSprite(g, o.look, Math.round((o.x - camX) * TS), Math.round((o.y - camY) * TS) - 4, G.npcDir[o.id] || "down", Math.sin(time / 600 + o.x) > 0.6 ? -1 : 0, 0)}); });
    const hx = Math.round((fx - camX) * TS), hy = Math.round((fy - camY) * TS) - 4;
    S.party.slice(1).forEach((id, i) => { const tr = S.trail[i]; if(tr) items.push({y:tr[1] - 0.01 * (i + 1), f:() => rpgSprite(g, tqLookOf(id), Math.round((tr[0] - camX) * TS), Math.round((tr[1] - camY) * TS) - 4, S.dir, 0, G.tw ? time / 120 : 0)}); });
    items.push({y:fy, f:() => rpgSprite(g, tqLookOf("hero"), hx, hy, S.dir, 0, G.tw ? time / 120 : 0, S.cx.rainbow)});
    items.sort((a, c) => a.y - c.y).forEach((it) => it.f());
    if(mp.tint){ g.fillStyle = mp.tint; g.fillRect(0, 0, 640, 360); }
    if(G.banner){
        const a = (time - G.banner.t) / 2600;
        if(a < 1){ g.globalAlpha = a < 0.8 ? 1 : (1 - a) / 0.2; g.fillStyle = "rgba(10,16,40,.78)"; rr(g, 12, 70, Math.min(456, 40 + G.banner.text.length * 16), 30, 8); g.fillStyle = "#fff"; g.font = "bold 16px sans-serif"; g.textAlign = "left"; g.textBaseline = "middle"; g.fillText(G.banner.text, 26, 86); g.globalAlpha = 1; }
        else G.banner = null;
    }
}
setInterval(() => { if(["map", "talk", "choice", "script", "shop", "gate", "menu", "rename", "battle", "end"].includes(G.mode)) paint(); }, 90);
setInterval(() => { if(G.S && ["map", "talk", "choice", "script", "shop", "gate", "menu", "battle"].includes(G.mode)) G.S.play++; }, 1000);
setInterval(() => { if(G.S && G.mode === "map") tqAutoSave(); }, 30000);

