// ---------------------------------------------------------------- どうぐ
const PK_BUFFS = {ITM001:["exp", 30, "けいけんち 2倍"], ITM002:["atk", 30, "こうげき 2倍"], ITM003:["def", 30, "ぼうぎょ 2倍"]};
