    if(u.quiz){ u.quiz = null; render(); return; }
    if(u.restOnly){ u.restOnly = false; u.open = false; u.tab = "home"; tqAutoSave(); G.mode = "map"; G.say = null; render(); return; }   // 休憩所の おねえさん：もどると マップへ
